return ['domain'=>'lingua-forge','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'hu_HU','project-id-version'=>'Lingua Forge 2.1.0','pot-creation-date'=>'2026-07-21T23:33:36+00:00','po-revision-date'=>'2026-07-05 21:04+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Többnyelvű útvonalkezelés, teljes többnyelvű SEO (hreflang, Open Graph, Schema.org, sitemap), és AI tartalom eszközök WordPresshez. Nyelvfelismerés, URL útvonalkezelés, fordítás, tartalomgenerálás, és egy teljes SEO réteg — nem szükséges kísérő plugin.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Fordítás','Lingua Forge — Quick Translate'=>'Lingua Forge — Gyors Fordítás','Informative'=>'Tájékoztató','Persuasive'=>'Meggyőző','Storytelling'=>'Történetmesélés','Technical'=>'Technikai','Conversational'=>'Beszélgetős','Permission denied.'=>'Engedély megtagadva.','Cannot determine target language from slug.'=>'Nem lehet meghatározni a célnyelvet a slug alapján.','Invalid post type.'=>'Érvénytelen poszt típus.','Invalid or primary language.'=>'Érvénytelen vagy elsődleges nyelv.','Template not found or not stored in the database.'=>'Sablon nem található vagy nincs az adatbázisban tárolva.','Template has no content.'=>'A sablonnak nincs tartalma.','No internal links found to update.'=>'Nem található belső hivatkozás frissítésre.','%d link updated.'=>'%d link frissítve.' . "\0" . '%d link frissítve.','No language-specific template parts found to map.'=>'Nem található nyelvspecifikus sablonrész a térképezéshez.','No template part references needed updating.'=>'Nincs szükség hivatkozás frissítésére a sablonrészben.','%d part reference updated.'=>'%d rész hivatkozás frissítve.' . "\0" . '%d rész hivatkozás frissítve.','Invalid language.'=>'Érvénytelen nyelv.','Template part not found or not stored in the database.'=>'Sablonrész nem található vagy nincs az adatbázisban tárolva.','Template part has no content.'=>'A sablonrésznek nincs tartalma.','No navigation references needed updating.'=>'Nincs szükség navigációs hivatkozás frissítésére.','%d navigation reference updated.'=>'%d navigációs hivatkozás frissítve.' . "\0" . '%d navigációs hivatkozás frissítve.','No AI provider configured.'=>'Nincs AI szolgáltató konfigurálva.','Missing pattern name or language.'=>'Hiányzik a minta neve vagy nyelv.','Pattern not found.'=>'Minta nem található.','Pattern has no content to translate.'=>'A minta nem tartalmaz fordítandó tartalmat.','AI provider returned an empty response.'=>'Az AI szolgáltató üres választ adott.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'A minta lefordítva és elmentve. Másolja a tartalmat a CPT bejegyzésébe a blokk szerkesztő mintabeillesztő segítségével, vagy használja kiindulópontként újrahasználható blokkhoz.','%d template repaired.'=>'%d sablon javítva.' . "\0" . '%d sablon javítva.','All template metadata is already up to date.'=>'Minden sablon metaadat már naprakész.','Invalid template type.'=>'Érvénytelen sablon típus.','Template "%s" already exists.'=>'A "%s" sablon már létezik.','Fix Links'=>'Hivatkozások javítása','Fix Parts'=>'Részek javítása','Re-create'=>'Újbóli létrehozás','"%s" recreated.'=>'"%s" újbóli létrehozása sikerült.','"%s" created.'=>'"%s" létrehozva.','Invalid template part.'=>'Érvénytelen sablonrész.','Template part "%s" already exists.'=>'A "%s" sablonrész már létezik.','Fix Nav'=>'Navigáció javítása','"%1$s" recreated. %2$d template updated.'=>'"%1$s" újbóli létrehozása sikerült. %2$d sablon frissítve lett.' . "\0" . '%2$d sablon frissítve lett.','"%1$s" created. %2$d template updated.'=>'"%1$s" létrehozva. %2$d sablon frissítve.' . "\0" . '"%1$s" létrehozva. %2$d sablon frissítve.','Page'=>'Oldal','Single'=>'Egyedi','Search'=>'Keresés','Search Results'=>'Keresési eredmények','Archive'=>'Archívum','Front Page'=>'Főoldal','Blog Home'=>'Blog kezdőlap','Single: %s'=>'Egység: %s','Single %s'=>'Egység %s','Archive: %s'=>'Archívum: %s','%s Archive'=>'%s archívum','No source content found to translate.'=>'Nem található forrástartalom a fordításhoz.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Fordítva. Ellenőrizze a Webhely Szerkesztőben — a belső hivatkozások, navigációs URL-ek és sablon szlógok nem frissülnek automatikusan.','Navigation not found.'=>'Navigáció nem található.','Navigation has no content to translate.'=>'A navigációnak nincs tartalma a fordításhoz.','"%1$s %2$s" saved.'=>'"%1$s %2$s" elmentve.','SEO Analysis'=>'SEO elemzés','Profile'=>'Profil','Details ↗'=>'Részletek ↗','/ 100'=>'/ 100','Overall SEO score'=>'Átfogó SEO pontszám','Metric'=>'Mértékegység','Finding'=>'Keresés','Title'=>'Cím','Meta description'=>'Meta leírás','Word count'=>'Szószám','Reading time'=>'Olvasási idő','Headings'=>'Címsorok','Images'=>'Képek','Links'=>'Linkek','AI Recommendations'=>'AI Ajánlások.','Run AI Analysis'=>'AI elemzés futtatása','Analyzing…'=>'Elemzés folyamatban…','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Állíts be egy AI szolgáltatót a Beállítások → API kulcsok alatt az AI-alapú ajánlások engedélyezéséhez.','AI analysis failed. Please try again.'=>'Az AI elemzés sikertelen volt. Kérjük, próbáld újra.','Suggested title'=>'Javasolt cím','Suggested meta description'=>'Javasolt meta leírás','Loaded from cache.'=>'Betöltve a gyorsítótárból.','↺ Refresh AI Analysis'=>'↺ AI elemzés frissítése','Analyse…'=>'Elemzés…','Analysis request failed. Please try again.'=>'Az elemzési kérés sikertelen volt. Kérjük, próbáld újra.','No translation found — analyzed the source language version.'=>'Nem található fordítás — az elemzett forrásnyelvi verziót.','Translate page…'=>'Oldal fordítása…','Generate content…'=>'Tartalom generálása…','AI Behaviour Preset'=>'AI viselkedés előbeállítás','Custom'=>'Egyéni','Global default (%s)'=>'Globális alapértelmezett (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Felülírja az AI előbeállítást a fordítás és tartalomgenerálás esetén ezen az oldalon. A webhely-szerte egyéni prompt utasítások (Beállítások → Viselkedés) mindig hozzáadódnak minden kéréshez, függetlenül ettől a választástól.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Felülírja az AI előbeállítást a fordítás és tartalomgenerálás esetén ezen az oldalon. Minden más funkció mindig az általános előbeállítást használja.','Close'=>'Bezárás','Translate missing'=>'Hiányzó fordítás','From'=>'Innen','Retranslate'=>'Újrafordítás','Retranslate every other language version from this post. Creates any that are missing and overwrites any that already exist — including the primary language, if this post is a translation.'=>'Fordítsa le újra ezt a bejegyzést az összes többi nyelvi verzióra. Létrehozza azokat, amelyek hiányoznak, és felülírja azokat, amelyek már léteznek — beleértve az elsődleges nyelvet is, ha ez a bejegyzés egy fordítás.','Sync'=>'Szinkronizálás','Reassign the correct language-specific template to every existing translation of this post. No AI call and no content changes — free and safe to run any time.'=>'Rendelje hozzá a helyes nyelvspecifikus sablont a bejegyzés minden meglévő fordításához. Nincs mesterséges intelligencia hívás és nincs tartalomváltozás — ingyenes és biztonságos bármikor futtatni.','Template Sync — reassign templates for every translation'=>'Sablonok szinkronizálása — sablonok újbóli hozzárendelése az összes fordításhoz','TS'=>'SZ','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Az utolsó szabályalapú SEO pontszám. Futtassa az elemzést a Beállítások → SEO → Elemzés menüpontban a frissítéshez.','Translating…'=>'Fordítás folyamatban…','Retranslating…'=>'Újrafordítás…','Syncing…'=>'Szinkronizálás folyamatban…','This retranslates every other language version of this post from this one — creating any that are missing and overwriting any that already exist (including the primary language, if this post is a translation). This cannot be undone. Continue?'=>'Ez újra lefordítja a bejegyzés minden más nyelvű verzióját ebből — létrehozza azokat, amelyek hiányoznak, és felülírja azokat, amelyek már léteznek (beleértve az elsődleges nyelvet is, ha ez a bejegyzés egy fordítás). Ezt nem lehet visszavonni. Folytatja?','Syncing templates…'=>'Sablonok szinkronizálása folyamatban…','✓ Done'=>'✓ Kész','Error'=>'Hiba','Navigation posts are translated via the Router tab, not this button.'=>'A navigációs bejegyzéseket a Router fülön fordítják, nem ezen a gombon.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'A "%s" típusú bejegyzések fordításához aktív integráció szükséges. Kérjük, győződjön meg arról, hogy a szükséges integráció telepítve és aktív.','No %s version found in this translation group.'=>'Nincs "%s" verzió ebben a fordítási csoportban.','Sync from a secondary-language WooCommerce product is disabled by default, since it would overwrite the primary product. Enable it in Settings → Behavior → WooCommerce if you want a translation to be able to become the new source content.'=>'A másodlagos nyelvű WooCommerce termékből való szinkronizálás alapértelmezés szerint le van tiltva, mivel felülírná az elsődleges terméket. Engedélyezze ezt a Beállítások → Viselkedés → WooCommerce helyen, ha azt szeretné, hogy egy fordítás legyen az új forrástartalomma.','Sync from a secondary-language post is disabled by default, since it would overwrite the primary post. Enable it in Settings → Behavior → Sync if you want a translation to be able to become the new source content.'=>'A másodlagos nyelvű bejegyzésből való szinkronizálás alapértelmezés szerint le van tiltva, mivel felülírná az elsődleges bejegyzést. Engedélyezze ezt a Beállítások → Viselkedés → Szinkronizálás helyen, ha azt szeretné, hogy egy fordítás legyen az új forrástartalomma.','Skipped — you do not have permission to edit the existing translation.'=>'Kihagyva — nincs engedélye a meglévő fordítás szerkesztéséhez.','Creating translations for post type "%s" requires an active integration.'=>'A "%s" bejegyzéstípushoz szükséges fordítások létrehozásához aktív integrációra van szükség.','Template Sync can only be run from the primary/source-language post.'=>'A Sablonok szinkronizálása csak az elsődleges/forrásnyelvi bejegyzésből futtatható.','Skipped — you do not have permission to edit this translation.'=>'Kihagyva — nincs engedélye a fordítás szerkesztéséhez.','Translation Caching'=>'Fordítás gyorsítótárazás','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'A Lingua Forge két független gyorsítótár réteget használ, hogy elkerülje az ismételt AI API hívásokat. Használja az alábbi lapokat mindegyik ellenőrzéséhez és kezeléséhez.','API Response Cache'=>'API válasz gyorsítótár','Translation Memory'=>'Fordítási memória','(disabled)'=>'Letiltva','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Egyedi cache az AI által generált fordításokhoz, meta leírásokhoz, kivonatokhoz és tartalomhoz. A bejegyzések automatikusan érvénytelenednek, amikor a tartalom vagy az AI szolgáltató/modell változik.','Enable API response caching'=>'API válasz gyorsítótár engedélyezése','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'Az API Válaszgyorsítótár minden AI kérés nyers eredményét tárolja — fordítás, meta leírás, kivonat és tartalom generálás — a bemenetek hash-je szerint (tartalom, nyelvpár, szolgáltató, modell). Kapcsolja ki prompt hangolásakor vagy amikor minden kérés el kell érje az AI szolgáltatót. A kikapcsolás nem törli a gyorsítótárban lévő bejegyzéseket — újra engedélyezésük visszaállítja azokat.','Save'=>'Mentés','Cached API responses'=>'Gyorsítótárazott API válaszok','API calls saved by cache'=>'API hívások gyorsítótárazva','(avg %.1f hits/entry)'=>'(átlag %.1f találat/bejegyzés)','Oldest cached response'=>'Legrégebbi gyorsított válasz','Most recent cached response'=>'Legutóbbi gyorsított válasz','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Törli az összes gyorsítótárazott AI eredményt? A jövőbeli kérések új API-hívásokat váltanak ki, amíg a gyorsítótár újraépül.','Clear API Response Cache'=>'API válasz gyorsítótárának törlése','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Blokk szintű fordítás gyorsítótár megosztva a bejegyzések között. Amikor engedélyezve van, azonos blokkok (azonos markup, nyelvpár és szójegyzék) gyorsítótárból kerülnek kiszolgálásra ahelyett, hogy újra hívnák az AI-t. A szójegyzék szerkesztése és a megfelelőségi preset változtatások automatikusan érvénytelenítik az érintett gyorsítótárban lévő fordításokat.','Enable block-level translation cache reuse across posts'=>'Engedélyezi a blokk szintű fordítási cache újrafelhasználását bejegyzések között','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Jelenleg kihagyva azoknál a bejegyzéseknél, amelyek blokk-kommentár attribútum helyettesítőket (wp:details összegző mezők stb.) használnak — ezek az eredeti egység hívásos fordítási útvonalra esnek.','Cached block translations'=>'Gyorsítótárazott blokk fordítások','Block translation reuses'=>'Blokk fordítási újrafelhasználások','(avg %.1f hits/block)'=>'(átlag %.1f találat/blokk)','Oldest cached block'=>'Legrégebbi gyorsított blokk','Most recent cached block'=>'Legutóbbi gyorsított blokk','Approximate size'=>'Körülbelüli méret','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Törli az összes Fordítási Memóriát? A jövőbeni fordítások újraépítik a gyorsítótárat, ahogy futnak.','Clear Translation Memory'=>'Fordítási memória törlése','API Response Cache setting saved.'=>'API válasz gyorsítótár beállítás mentve.','Translation Memory setting saved.'=>'A Fordítási memória beállítás mentve.','AI cache cleared. %d entry was removed.'=>'Az AI gyorsítótár törölve. %d bejegyzés lett eltávolítva.' . "\0" . 'Az AI gyorsítótár törölve. %d bejegyzés lett eltávolítva.','Translation Memory cleared. %d cached block was removed.'=>'Fordítási memória törölve. %d gyorsítótárazott blokk lett eltávolítva.' . "\0" . 'Fordítási memória törölve. %d gyorsítótárazott blokk lett eltávolítva.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'A Lingua Forge egy teljes körű többnyelvű SEO megoldás. Nincs szükség további SEO bővítményre.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Ha általános SEO bővítményt telepített, ez a panel mutatja, hogyan alkalmazkodik LF a duplikált kimenet elkerüléséhez. A cél az ütközés elkerülése — nem az együttműködés. LF mindig biztosítja a többnyelvű SEO réteget (hreflang, og:locale, inLanguage séma), amelyhez ismerni kell LF nyelvi útvonal konfigurációját a helyes előállításhoz.','Installed SEO plugins'=>'Telepített SEO bővítmények','Plugin'=>'Bővítmény','Status'=>'Állapot','✓ Active'=>'✓ Aktív','— Not detected'=>'— Nem észlelve','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Nem észlelt ütköző SEO bővítményeket. A Lingua Forge függetlenül kezeli az összes SEO kimenetet.','What LF provides — and collision avoidance'=>'Amit az LF nyújt — és az ütközés elkerülése','Feature'=>'Funkció','LF provides'=>'LF biztosít','When another SEO plugin is installed'=>'Amikor más SEO plugin van telepítve','Hreflang'=>'Hreflang','Disabled (by setting)'=>'Letiltva (beállítással)','✓ LF outputs — plugin hreflang suppressed'=>'✓ LF kimenetek — plugin hreflang elnyomva','✓ LF outputs'=>'✓ LF kimenetek','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF pontosan adja meg a hreflang értékeket minden konfigurált nyelvhez, beleértve az x-default-ot is. Az általános SEO bővítmények nem férnek hozzá az LF útvonal konfigurációhoz, és helytelen URL-elképzeléseken alapuló hreflang értékeket generálnának. Az LF szűrőn keresztül elnyomja azok kimenetét, hogy elkerülje az ütközéseket.','Suppressed: %s.'=>'Elnyomva: %s.','Open Graph'=>'Open Graph','Disabled (mode setting)'=>'Letiltva (mód beállítással)','→ Locale tags only — deferring base OG to plugin'=>'→ Csak helyi címkék — az alap OG késleltetése a pluginre','→ Locale tags only (manual setting)'=>'→ Csak helyi címkék (kézi beállítás)','✓ LF outputs full OG + Twitter Cards'=>'✓ LF kimenetek teljes OG + Twitter kártyák','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF mindig hozzáadja az og:locale és og:locale:alternate címkéket — a többnyelvű OG jeleket, amelyeket egy általános SEO bővítmény nem tud helyesen előállítani. A bázis OG készlethez (og:title, og:description, og:image) akkor adja ki, amikor nincs más bővítmény. Ha SEO bővítmény van telepítve, LF kihagyja az alap készletet a duplikált címkék elkerülése érdekében — nem azért, mert a bővítmény "jobb", hanem mert a duplikáció nem nyújt értéket.','Schema.org JSON-LD'=>'Schema.org JSON-LD','— Deferred to plugin'=>'— Át lett helyezve a pluginhez','✓ LF outputs Article / WebPage / WebSite'=>'✓ LF kimenetek Cikk / Weboldal / Webhely','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF többnyelvű JSON-LD-t ad ki, amelyben az inLanguage megjegyzések kötődnek az útválasztási konfigurációhoz. Amikor egy SEO bővítmény van telepítve, az LF teljesen letiltja saját sémáját: a duplikált JSON-LD gráfok érvényesítési hibákat okoznak, és nincs tiszta módja meglévő gráf kiegészítésének.','XML Sitemap'=>'XML Sitemap','✓ Active at /lf-sitemap.xml'=>'✓ Aktív a /lf-sitemap.xml fájlban','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF saját oldaltérképet generál xhtml:link alternatívákkal minden fordítási csoporthoz. Amikor SEO bővítmény van telepítve, az külön oldaltérképet generál — mindkettő függetlenül létezik. Mindkettőt küldje be a Google Search Console-ba: a SEO bővítmény oldaltérképe a tartalom felfedezéséhez, az LF oldaltérképe a nyelvi kapcsolatok jeleinek.','Canonical tag'=>'Kanonikus címke.','✓ WP canonical replaced (self-referencing)'=>'✓ WP kanonikus URL cseréje (önhivatkozó)','WP core canonical active (hreflang disabled)'=>'A WP mag alapértelmezett canonical (hreflang kikapcsolva)','LF removes the WordPress core canonical tag and replaces it with a self-referencing canonical pointing to the correct language-prefixed URL. When a third-party SEO plugin (Yoast, Rank Math, AIOSEO, SEOPress) is active, LF defers canonical management to that plugin entirely.'=>'A LF eltávolítja a WordPress alapértelmezett kanonikus címkét, és egy önhivatkozó kanonikus URL-re cseréli, amely a helyes nyelv előtaggal ellátott URL-re mutat. Amikor egy harmadik fél SEO-bővítménye (Yoast, Rank Math, AIOSEO, SEOPress) aktív, a LF teljes mértékben átadja a kanonikus kezelését ennek a bővítménynek.','Legacy lf-social-share mu-plugin'=>'Régi lf-social-share mu-plugin','The lf-social-share mu-plugin is active.'=>'Az lf-social-share mu-plugin aktív.','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'A Lingua Forge beépített Social Share és Open Graph moduljai lefedik az összes funkciót, amit a mu-plugin nyújt, plusz többnyelvű og:locale támogatást. Biztonságosan deaktiválhatja a mu-plugin-t.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'OG/Twitter Card címkék: az LF Open Graph modulja kezeli (SEO → Open Graph & Twitter Cards)','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Közösségi ikonok blokk megosztása: URL-ek: LF beépített Közösségi Megosztás (SEO → Közösségi Megosztás) által kezelt','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'másolt/native/auto JS műveletek: LF social-share.js által kezelt','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Amíg aktív, a mu-plugin kezeli az alap OG készletet, és az LF csak a helyi címkéket (automatikus mód) adja hozzá. Eltávolítása automatikusan átváltja az LF-t a teljes OG módra.','Debug Files'=>'Hibakereső fájlok','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Amikor a hibakereső naplózás engedélyezve van (az alábbi kapcsolóval vagy a wp-config.php fájlban a LINGUAFORGE_AI_DEBUG definícióval), a Fordítás és az FSE sablon fordítási funkciók nyers AI promptokat és válaszokat írnak a lemezre hibakeresés céljából. Használd ezt a részt a kimenet figyelésére, és töröld, miután megvan, amire szükséged van — a fájlok gyorsan növekedhetnek nagy oldalakon. Állítsd be a célkönyvtárat a linguaforge_debug_dir szűrő segítségével.','Debug files cleared. %d file was removed.'=>'Hibakereső fájlok törölve. %d fájl lett eltávolítva.' . "\0" . 'Hibakereső fájlok törölve. %d fájl lett eltávolítva.','Debug logging enabled.'=>'Hibakereső naplózás engedélyezve.','Debug logging disabled.'=>'Hibakereső naplózás letiltva.','Debug logging'=>'Hibakereső naplózás','Write AI prompts and responses to disk for troubleshooting'=>'AI promptok és válaszok írása a lemezre hibakereséshez','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Kényszerítve BE a wp-config.php fájlban a LINGUAFORGE_AI_DEBUG állandó által. Töröld ezt a sort, hogy innen irányítsd ezt a kapcsolót.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Kényszerítve KI a wp-config.php fájlban a LINGUAFORGE_AI_DEBUG állandó által. Töröld ezt a sort, hogy innen irányítsd ezt a kapcsolót.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'A fájlok az alábbi könyvtárba kerülnek. Hasznos fordítási problémák diagnosztizálásához — kapcsold ki, miután megvan, amire szükséged van, hogy a fájlok ne halmozódjanak. Ezt a wp-config.php fájlból is kényszerítheted a `define( \'LINGUAFORGE_AI_DEBUG\', true );` sorral, ami felülírja ezt a kapcsolót.','Currently:'=>'Jelenleg:','✓ Enabled'=>'✓ Engedélyezve','✗ Disabled'=>'✗ Letiltva','Directory'=>'Könyvtár','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Szűrő a linguaforge_debug_dir segítségével, hogy a hibakereső kimenetet nem nyilvános helyre irányítsd.','Files'=>'Fájlok','.txt file(s) in the directory'=>'.txt fájl(ok) a könyvtárban','Save Debug Setting'=>'Hibakereső beállítás mentése','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Törli az összes .txt fájlt a hibakereső könyvtárban? A könyvtár maga megmarad, így a jövőbeni hibakereső írások még mindig ide kerülnek.','Clear Debug Files'=>'Hibakereső fájlok törlése','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'A Lingua Forge minden konfigurált nyelvhez <link rel="alternate" hreflang> tageket ad minden oldalhoz, beleértve az x-default-et, amely a forrásnyelvre mutat. Ez az elsődleges többnyelvű SEO jelzés a Google és más keresőmotorok számára — nincs szükség további SEO pluginre.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Amikor a Yoast SEO, Rank Math, All in One SEO vagy SEOPress aktív, a Lingua Forge automatikusan elnyomja azok hreflang kimenetét szűrőn keresztül. Az általános SEO pluginek egynyelvű URL-struktúrán alapuló hreflang-et generálnak, és nem tudják figyelembe venni a többnyelvű útvonal konfigurációt; az LF kimenete mindig helyes.','Hreflang settings saved.'=>'Hreflang beállítások mentve.','Hreflang output'=>'Hreflang kimenet','Output hreflang tags in wp_head'=>'Hreflang címkék kiírása a wp_head-ben','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Letiltás csak fej nélküli oldalak vagy teljesen egyedi hreflang megvalósítások esetén. Kikapcsoláskor LF már nem távolítja el a WordPress mag canonical címkét, és nem szünteti meg az SEO-bővítmények hreflang kimenetét.','Current status'=>'Aktuális állapot','✓ Hreflang active'=>'✓ Hreflang aktív','LF is outputting hreflang tags and is replacing the WordPress core canonical with a self-referencing canonical for each language version.'=>'Az LF hreflang címkéket ad ki, és az WordPress alapvető canonical címkét minden nyelvverzióhoz önmagára hivatkozó canonical címkével helyettesíti.','LF is suppressing hreflang output from: %s'=>'LF elnyomja a hreflang kimenetet: %s','Save Hreflang Settings'=>'Hreflang beállítások mentése','Language Overrides'=>'Nyelvi felülírások','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Feltöltött .mo fájlok felülírják a harmadik féltől származó bővítmények szövegeit adott helyeken — például egy egyedi VikBooking fordítás, amely az "apartman" szót használja a "szoba" helyett. A fájloknak követniük kell a WordPress névkonvenciót: {textdomain}-{locale}.mo (pl. vikbooking-ca.mo). Ezek a feltöltött mappában tárolódnak, és túlélnek bővítményfrissítéseket.','Override file uploaded successfully.'=>'A felülíró fájl sikeresen feltöltve.','Override file deleted.'=>'A felülíró fájl törölve.','No file was selected.'=>'Nem választott ki fájlt.','Only .mo files are accepted.'=>'Csak .mo fájlokat fogadunk el.','The upload failed — please try again.'=>'A feltöltés sikertelen volt — próbálja újra.','Could not save the file. Check that the uploads folder is writable.'=>'Nem sikerült elmenteni a fájlt. Ellenőrizze, hogy a feltöltési mappa írható-e.','Invalid filename.'=>'Érvénytelen fájl név.','Security check failed — file path is not permitted.'=>'Biztonsági ellenőrzés sikertelen — a fájl útvonala nem megengedett.','An unknown error occurred.'=>'Ismeretlen hiba történt.','Text domain / locale'=>'Szöveg domain / hely','Size'=>'Méret','Delete all files for this override (both .mo and .po)?'=>'Törli az összes fájlt ehhez a felülíráshoz (mind .mo, mind .po)?','Delete'=>'Törlés','No override files uploaded yet.'=>'Még nem töltött fel felülíró fájlokat.','Upload .mo file'=>'Feltöltés .mo fájl','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Csak összerakott .mo fájlokat fogad el. A fájlnak követnie kell a {textdomain}-{locale}.mo} mintát. Egy meglévő fájl ugyanilyen nevével való feltöltés felülírja azt.','Upload Override'=>'Felülírás feltöltése','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Másolás biztonságos tárolásba','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'A Loco Translate a saját fordításait a wp-content/languages/loco/ helyen tárolja — ez a helyszín csendben törölhető egy WP magfrissítés, bővítmény újratelepítés vagy a Loco Translate eltávolítása esetén. A fájlok ide való másolásával azok átkerülnek a Lingua Forge i18n-overrides könyvtárba, amely minden ilyen eseményen túléli, és automatikusan betöltődik minden kérésnél.','File copied to safe storage successfully.'=>'A fájl sikeresen másolva a biztonságos tárolásba.','Source file not found.'=>'A forrásfájl nem található.','Could not copy the file. Check that the uploads folder is writable.'=>'Nem sikerült másolni a fájlt. Ellenőrizze, hogy a feltöltési mappa írható-e.','Invalid file reference.'=>'Érvénytelen fájl hivatkozás.','Type'=>'Típus','✓ In safe storage'=>'✓ Biztonságos tárolásban','Copy to safe storage'=>'Másolás biztonságos tárolásba','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Még nem találhatók egyedi Loco Translate fájlok. Ezek itt jelennek meg, amint elment egy fordítást a Loco Translate-ben.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'A Lingua Forge Open Graph és Twitter Card meta címkéket ad ki, így a megosztott URL-ek helyes nyelvet, címet, leírást és képet jelenítenek meg a közösségi platformokon.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Ellentétben a hreflang-gel — ahol a LF mindig felülírja a többi plugint, mert azok nem ismerhetik a többnyelvű konfigurációt — az Open Graph más: a Yoast, Rank Math és hasonló pluginek már helyesen generálják az OG címkéket a tartalomhoz. A duplikálásuk nem ad hozzá értéket. Automatikus módban a LF észleli az aktív SEO plugineket, és csak azokat az elemeket adja hozzá, amiket azok nem tudnak biztosítani: og:locale (aktuális nyelv) és og:locale:alternate (minden más konfigurált nyelv).','Open Graph settings saved.'=>'Open Graph beállítások mentve.','Open Graph output'=>'Open Graph kimenet','Output Open Graph tags in wp_head'=>'Open Graph címkék kiírása a wp_head-ben','Output mode'=>'Kimeneti mód','Auto (recommended)'=>'Automatikus (ajánlott).','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Aktív SEO bővítmények (Yoast, Rank Math stb.) felismerése futásidőben. Csak og:locale + og:locale:alternate kibocsátása, amikor egy másik bővítmény már kiadja a teljes OG készletet; a teljes készlet kibocsátása, amikor egy sem kerül felismerésre.','Locale only'=>'Csak helyi','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Mindig csak az og:locale és og:locale:alternate-t küldje. Használja, ha egy másik plugin vagy téma kezeli a teljes OG készletet.','Full'=>'Teljes','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Mindig küldje el a teljes OG + Twitter Card készletet, függetlenül más pluginoktól. Csak akkor használja, ha más plugin nem adja ki az OG tageket.','Disabled'=>'Letiltva','Do not output any OG tags.'=>'Ne adjon ki OG címkéket.','Default OG image'=>'Alapértelmezett OG kép','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'Helyettesítő kép URL, ha az oldalnak nincs kiemelt kép, oldal logó vagy ikon. Megjelenik a közösségi előnézetekben az archívumok, a blog index és bármely egyedi oldal esetén, amelynek nincs bélyegképe.','— Disabled'=>'— Kikapcsolva','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Aktív — csak helyi címkék (og:locale, og:locale:alternate)','✓ Active — full OG + Twitter Cards'=>'✓ Aktív — teljes OG + Twitter kártyák','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Régi lf-social-share mu-plugin észlelve. LF a bázis OG készletet a mu-pluginra hagyja, és csak og:locale + og:locale:alternate-t ad ki. A mu-plugin deaktiválható — LF beépített Social Share (SEO → Social Share fül) és Open Graph ugyanazt a funkciót fedik le.','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Észlelt SEO plugin(ek): %s. LF csak az og:locale és og:locale:alternate értékeket adja ki; az észlelt plugin kezeli a teljes OG készletet.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Nem észlelt külső OG bővítményt. Az LF a teljes OG + Twitter Card készletet adja ki.','Save Open Graph Settings'=>'Open Graph beállítások mentése','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'A Lingua Forge Schema.org JSON-LD strukturált adatokat ad ki, hogy a keresőmotorok megértsék tartalom típusát, nyelvét és metaadatait. Ez az elsődleges módja annak, hogy inLanguage megjegyzéseket közöljünk a többnyelvű tartalomról a Google és más keresőrobotok felé.','Schema output deferred.'=>'A Schema kimenet késleltetve.','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s aktív és már kiadja a Schema.org JSON-LD-t. A Lingua Forge letiltotta saját séma kimenetét, hogy elkerülje az ütköző gráfokat. Ellentétben az Open Graph-tal — ahol az LF hozzáadja az og:locale-t egy másik plugin kimenete fölé — a séma nem egészíthető ki tisztán: duplikált vagy átfedő JSON-LD gráfok érvényesítési hibákat okoznak. Kapcsold ki a séma kimenetet a detektált pluginben, ha az LF-től szeretnéd kezelni a strukturált adatokat.','Schema.org settings saved.'=>'Schema.org beállítások mentése.','Schema.org output'=>'Schema.org kimenet','Output Schema.org JSON-LD in wp_head'=>'Kimeneti Schema.org JSON-LD a wp_head-ben','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Zárolva — egy ütköző SEO bővítmény aktív. Lásd a fent említett értesítést.','Article / WebPage'=>'Cikk / Weboldal.','Output Article or WebPage schema on singular posts and pages'=>'Kimeneti Article vagy WebPage séma egyes bejegyzéseken és oldalakon','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'A blogbejegyzések a Cikket használják; minden más bejegyzéstípus és oldal a Weboldal. Tartalmazza a címet, leírást, inLanguage-t, url-t, közzététel dátumát, módosítás dátumát, képet és kiadót.','WebSite'=>'Weboldal','Output WebSite schema on the front page and blog index'=>'Weboldal séma a főoldalon és a blog indexen','Includes site name, url, and inLanguage.'=>'Tartalmazza az oldal nevét, url-jét és inLanguage-t.','Product'=>'Termék','Output Product schema on WooCommerce product pages'=>'Termék séma kiírása a WooCommerce termékoldalakon','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Tartalmazza a nevet, leírást, inLanguage-t, url-t, képet, valamint egy Ajánlatot ár, árfolyam és elérhetőség adatokkal. Az ár és az elérhetőség a forrásnyelvű termékből származik (megosztott készlet modell).','Currently emitting'=>'Jelenleg kibocsátás','Article / WebPage — all singular posts and pages'=>'Cikk / Weboldal — összes egyedi bejegyzés és oldal.','WebSite — front page / blog index'=>'Weboldal — főoldal / blog index','Product — WooCommerce product pages'=>'Termék — WooCommerce termékoldalak','Nothing — all types disabled'=>'Semmi — minden típus le van tiltva','Save Schema.org Settings'=>'Schema.org beállítások mentése','Blog / Editorial'=>'Blog / Szerkesztői','Product / eCommerce'=>'Termék / eCommerce','Landing / Short-form'=>'Földi / Rövid formátum','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Szűrés nyelv és bejegyzéstípus szerint, böngésszen a tartalmán, és kattintson az Elemzésre bármely elemnél, hogy szabályalapú SEO ellenőrzést futtasson — cím hosszúsága, meta leírás, szavak száma, fejléc szerkezet, kép alt lefedettség és belső linkek.','Treat H2 as H1 equivalent'=>'Treat H2 as H1 equivalent','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Engedélyezze, amikor a témája a bejegyzés címet H2-ként jeleníti meg H1 helyett (gyakori néhány blokk témában). Az elemző lekéri a renderelt oldalt, és ha nem talál H1-et, de talál H2-t, akkor az első H2-t H1-re emeli az értékeléshez.','Save analysis settings'=>'Elemzési beállítások mentése','Per-Post Analysis'=>'Egyedi bejegyzés elemzése','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Válasszon ki egy bejegyzést, és futtasson részletes SEO auditot, hogy lássa az egyes metrikák eredményeit és az adott elemre vonatkozó pontszámot.','Language'=>'Nyelv','source'=>'forrás','All types'=>'Minden típus.','Load content'=>'Tartalom betöltése','Batch Analysis'=>'Kötegelt elemzés','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Teljes SEO audit futtatása az összes közzétett bejegyzésen egy vagy összes aktív nyelven. Az eredmények bejegyzésenként vannak mentve, és a nyelvi oszlop badge-jeiben tükröződnek a bejegyzés listában.','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'A WooCommerce rendszeroldalak (Bolt, Kosár, Fizetés, Saját fiók) kizárva — tartalmukat a WooCommerce kezeli, és nem javíthatók SEO szerkesztésekkel.','Post type'=>'Bejegyzéstípus','Default profile'=>'Alapértelmezett profil','— Auto-detect —'=>'— Automatikus felismerés —','Analyse all languages'=>'Összes nyelv elemzése','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'Automatikus észlelés: WooCommerce termékek → Termékprofil; statikus főoldal → Landoló profil; minden más → Blog profil. Válasszon egy adott profilt, hogy felülírja ezt minden bejegyzésnél.','%d post'=>'%d bejegyzés' . "\0" . '%d bejegyzés','Last run: %s ago'=>'Utolsó futás: %s óta','Never run'=>'Soha ne futtass','avg'=>'átlag','(partial)'=>'(részleges)','Analyse'=>'Elemzés','(no title) #%d'=>'(nincs cím) #%d','Invalid post ID.'=>'Érvénytelen bejegyzés azonosító.','Post not found or not published.'=>'A bejegyzés nem található vagy nincs közzétéve.','~%d min read'=>'~%d perc olvasás' . "\0" . '~%d perc olvasás','No title set.'=>'Nincs cím beállítva.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'A cím %1$d karakter — a SERPben csonkolódhat (célzottan %2$d alatt).','Title is only %d chars — aim for at least 10 characters.'=>'A cím csak %d karakter — legalább 10 karaktert célozz meg.','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Egyszavas cím (%d karakter) — egy második szó hozzáadása javítja az érthetőséget és a kulcsszó lefedettséget.','%1$d chars, %2$d words — good title.'=>'%1$d karakter, %2$d szó — jó cím.','Using LF AI meta description.'=>'LF AI meta leírás használata.','No LF meta description set — using excerpt/content.'=>'Nincs LF meta leírás beállítva — az kivonatot/tartalmat használja.','No meta description found. Generate one via the AI meta description feature.'=>'Nem található meta leírás. Generáljon egyet az AI meta leírás funkcióval.','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d karakter — túl rövid (célozz %2$d–%3$d felé). %4$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d karakter — valószínűleg levágva a SERP-eken (tartsd kevesebb mint %2$d). %3$s','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d karakter — jó, kissé meghaladja az ideális %2$d-t, de még elfogadható a %3$d karakteres tartományon belül. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d karakter — ideális hossz. %2$s','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d szó — nagyon vékony tartalom. Fontolja meg a kiterjesztést legalább %2$d szóra.','%1$d words — below recommended minimum of %2$d.'=>'%1$d szó — az ajánlott minimum %2$d alatt van.','%d words.'=>'%d szó.','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'H2-H1 mód engedélyezve — a cím H1-nek számít. (A fejléc címkék nem voltak észlelhetők a renderelt oldalról; ellenőrizze, hogy a témája helyesen jeleníti-e meg a címet.)','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Nem található H1. Általában a bejegyzés címe az H1 — ellenőrizze, hogy a témája kiadja-e.','%d H1 tags found — a page should have exactly one H1.'=>'%d H1 cím található — egy oldalnak pontosan egy H1 címet kell tartalmaznia.','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — nincs H2, de %d H3 alcím található (pl. akordeon/detaily fejléc). A szerkezet elfogadható.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — rövid tartalom (%d bekezdés), alcímek nem szükségesek.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — nincs H2 alcím (elfogadható ebben a tartalomtípusban).','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — nem található H2 vagy H3 alcím. A H2-k hozzáadása javítja a szerkezetet.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','No images found in content.'=>'Nem található képek a tartalomban.','%1$d of %2$d image(s) missing alt text.'=>'%1$d kép hiányzik az alt szövegből, összesen %2$d kép.','%d image(s), all have alt text.'=>'%d kép, mindegyik rendelkezik alt szöveggel.','No links found. Internal links improve crawlability and user navigation.'=>'Nem található linkek. A belső linkek javítják a feltérképezhetőséget és a felhasználói navigációt.','No links found.'=>'Nem található link.','%d external link(s), no internal links. Add internal links to related content.'=>'%d külső hivatkozás, nincs belső hivatkozás. Adj hozzá belső hivatkozásokat kapcsolódó tartalomhoz.','%d external link(s), no internal links.'=>'%d külső hivatkozás, nincs belső hivatkozás.','%1$d internal, %2$d external.'=>'%1$d belső, %2$d külső.','Post not found.'=>'A bejegyzés nem található.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Nincs AI szolgáltató konfigurálva. Adj hozzá API kulcsot a Beállítások → API kulcsok menüpontban.','No response from AI provider. Check your API key and try again.'=>'Nincs válasz az AI szolgáltatótól. Ellenőrizze az API kulcsot, és próbálja újra.','AI returned an unexpected response format. Please try again.'=>'Az AI váratlan választ adott. Kérjük, próbáld újra.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'A Lingua Forge egy dedikált XML oldaltérképet generál /lf-sitemap.xml címen, amely nyelvi alternatív linkeket ad hozzá az összes fordított tartalomhoz. Ez az oldal térkép kiegészíti a WordPress mag oldal térképét és bármely SEO bővítmény oldal térképét — nem helyettesíti azokat.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'A WordPress mag sitemapja felsorolja az összes tartalom URL-jét. Az LF sitemap megmutatja a keresőmotoroknak, hogyan viszonyulnak egymáshoz a nyelvi változatok az xhtml:link hreflang alternatívák révén. Mindkettőt küldje el a Google Search Console-ba a teljes lefedettség érdekében.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s aktív és saját térképet generál. Ez a térkép külön van az LF-től. Mindkettőt küldd be a Google Search Console-ba: az SEO plugin térképe tartalmazza a tartalmadat; az LF térképe hozzáadja a többnyelvű alternatív linkeket. Az LF térképe automatikusan be van jelentve a robots.txt-ben.','Sitemap settings saved.'=>'Oldaltérkép beállítások mentése.','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Az oldaltérkép gyorsítótára ürítve. A következő látogatáskor újra generálódik az oldaltérkép URL-jén.','Sitemap output'=>'Oldaltérkép kimenet','Generate the multilingual sitemap at /lf-sitemap.xml'=>'A többnyelvű oldaltérképet a /lf-sitemap.xml címen generálja','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Amikor engedélyezve van, a sitemap URL automatikusan be van jelentve a robots.txt-ben, és a gyorsítótár frissül, amikor a fordított tartalom mentésre kerül.','Sitemap URL'=>'Oldaltérkép URL','Submit this URL to Google Search Console alongside your main sitemap.'=>'Küldje ezt a URL-t a Google Search Console-ba a fő sitemapja mellett.','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Még nem generált. Az oldal térkép az első látogatáskor épül fel az oldal térkép URL-jén, és 24 órán keresztül cache-elve van.','✓ Active — %d URL entry with language alternates'=>'✓ Aktív — %d URL bejegyzés nyelvi alternatívákkal' . "\0" . '✓ Aktív — %d URL bejegyzés nyelvi alternatívákkal','No translated content found. The sitemap will populate once posts have been translated.'=>'Nem található fordított tartalom. Az oldal térkép feltöltődik, amint a bejegyzéseket lefordították.','Last generated: %s'=>'Utolsó generálás: %s','Save Sitemap Settings'=>'Oldaltérkép beállítások mentése','Flush Sitemap Cache'=>'Oldaltérkép gyorsítótár ürítése','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Következő kérésnél újra generálja az oldaltérképet. Használja tömeges importálás vagy fordítási kapcsolatok manuális szerkesztése után.','IndexNow'=>'IndexNow','IndexNow is an open protocol supported by Bing, Yandex, and other search engines. When a translated post is published or updated, Lingua Forge automatically notifies all participating engines in a single push — no polling, no waiting for the next robots.txt crawl.'=>'Az IndexNow egy nyílt protokoll, amelyet a Bing, Yandex és más keresőmotorok támogatnak. Amikor egy fordított bejegyzés közzéteszik vagy frissítik, a Lingua Forge automatikusan értesíti az összes részt vevő motort egyetlen push-sal — nincs lekérdezés, nincs várakozás a következő robots.txt feltérképezésre.','IndexNow replaces the deprecated Bing and Yandex sitemap-ping endpoints. Google discovers sitemaps via the robots.txt Sitemap: directive as before.'=>'Az IndexNow helyettesíti a régi Bing és Yandex sitemap-ping végpontokat. A Google a robots.txt Sitemap: utasítással fedezi fel a térképeket, mint korábban.','✓ All URLs submitted to IndexNow successfully.'=>'✓ Minden URL sikeresen beküldve az IndexNow-ba.','No translated URLs found to submit. Publish some translated posts first.'=>'Nincs elküldendő fordított URL. Először tegyen közzé néhány fordított bejegyzést.','✗ IndexNow submission failed. Check that the key file is publicly reachable (see below) and try again.'=>'✗ Az IndexNow beküldés sikertelen. Ellenőrizze, hogy a kulcsfájl nyilvánosan elérhető-e (lásd alább), és próbálja újra.','Verification key'=>'Ellenőrző kulcs','Key file served automatically at: %s'=>'A kulcsfájl automatikusan elérhető: %s','Key could not be generated. Check that the site has write access to WordPress options.'=>'Nem sikerült generálni a kulcsot. Ellenőrizze, hogy a webhely írhat-e a WordPress beállításokhoz.','Key file status'=>'Kulcsfájl állapota','✓ Key file is publicly reachable.'=>'✓ A kulcsfájl nyilvánosan elérhető.','✗ Key file is not reachable.'=>'✗ A kulcsfájl nem elérhető.','IndexNow engines verify the key file before accepting submissions. If the file is not reachable, submissions will be rejected with a 403 error.'=>'Az IndexNow motorok ellenőrzik a kulcsfájlt, mielőtt elfogadnák a beküldéseket. Ha a fájl nem elérhető, a beküldéseket 403-as hibával utasítják el.','Common causes: full-page caching (clear it), a security plugin blocking .txt files, or a custom Nginx/Apache rule. The file is served by LF on every request — no physical file is written to disk.'=>'Általános okok: teljes oldal gyorsítótárazás (törölje), egy biztonsági bővítmény blokkolja a .txt fájlokat, vagy egy egyedi Nginx/Apache szabály. A fájlt a LF minden kérésnél kiszolgálja — nem ír fizikai fájlt a lemezre.','Submit all URLs'=>'Küldje be az összes URL-t','Submit all URLs via IndexNow'=>'Minden URL beküldése az IndexNow-on keresztül','Pushes every published, LF-managed URL to IndexNow in one batch. Automatic submission already runs on every publish/update — use this only after a bulk import or when setting up IndexNow for the first time.'=>'Minden közzétett, LF által kezelt URL-t egy csomagban push-ol az IndexNow-ba. Az automatikus beküldés már minden közzétételnél/felülírásnál fut — csak tömeges import vagy az IndexNow első beállításakor használja.','Google does not participate in IndexNow. It discovers sitemaps via the robots.txt Sitemap: directive — which LF has already configured. Use Google Search Console to monitor indexing coverage.'=>'A Google nem vesz részt az IndexNow-ban. A sitemapokat a robots.txt Sitemap: direktívájával fedezi fel — amelyet az LF már konfigurált. A Google Search Console segítségével figyelheti az indexelési lefedettséget.','Open Search Console →'=>'Nyissa meg a Search Console-t →','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt frissítve Sitemap utasítással.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Fizikai robots.txt található. LF Sitemap irányelve jelen van.','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Fizikai robots.txt fájl létezik a webhely gyökérben. A WordPress virtuális robots.txt-e — és az LF Térkép: szűrő — megkerüli ezeket. Az LF térképe nincs bejelentve a keresőmotoroknak.','Add Sitemap directive to robots.txt'=>'Add hozzá a Sitemap utasítást a robots.txt-hez.','Appends the following line to your existing robots.txt: %s'=>'A következő sort fűzi hozzá a meglévő robots.txt fájlhoz: %s','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS van beállítva.','Add the following line to your robots.txt manually:'=>'Add hozzá a következő sort a robots.txt-hez manuálisan:','View current robots.txt'=>'Jelenlegi robots.txt megtekintése','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Nem található fizikai robots.txt fájl. A WordPress virtuálisan generálja, és az LF oldal térkép direktívája automatikusan be van állítva.','The following directive is active in your virtual robots.txt:'=>'A következő utasítás aktív a virtuális robots.txt fájlban:','File modifications are disabled (DISALLOW_FILE_MODS).'=>'A fájl módosítások le vannak tiltva (DISALLOW_FILE_MODS).','Could not write to robots.txt. Check file permissions.'=>'Nem sikerült írni a robots.txt-be. Ellenőrizze a fájl jogosultságait.','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'A Lingua Forge kibővíti a WordPress Core Social Icons blokkot dinamikus megosztási URL-ekkel. Állítson be bármely ikon linkjét "share:" értékre, és az LF átírja a helyes megosztási URL-re vagy JavaScript műveletre a renderelés idején — nem szükséges egyedi kód vagy harmadik féltől származó bővítmény.','Social Share settings saved.'=>'A közösségi megosztási beállításokat elmentettük.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'Az lf-social-share mu-plugin aktív. A Lingua Forge beépített közösségi megosztása inaktív — a mu-plugin kezeli a megosztási URL átírását és a JS műveleteket.','Social Share'=>'Közösségi Megosztás','Enable Social Share URL rewriting for Social Icons blocks'=>'Társadalmi megosztási URL átírás engedélyezése a Social Icons blokkokhoz','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Már a lf-social-share mu-plugin biztosítja ezt a funkciót, ezért nem engedélyezett.','Save Social Share Settings'=>'Közösségi megosztási beállítások mentése','How to use'=>'Hogyan használjuk','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'A blokk szerkesztőben adj hozzá egy Social Icons blokkot. Minden ikon esetén nyisd meg a link beállításokat, és írd be az alábbi "share:" értékek egyikét URL-ként. A frontenden LF helyettesíti a megfelelő megosztási URL-lel a jelenlegi oldalhoz.','External share services'=>'Külső megosztási szolgáltatások','URL to enter'=>'Beírandó URL','Action'=>'Akció','Share on Facebook'=>'Megosztás Facebookon','Post on X / Twitter'=>'Bejegyzés X / Twitteren','Share on LinkedIn'=>'Megosztás LinkedInen','Send via WhatsApp'=>'Küldés WhatsApp-on keresztül','Send via Telegram'=>'Küldés Telegramon keresztül','Submit to Reddit'=>'Küldés a Redditre','Pin on Pinterest'=>'Pin a Pinteresten','Share on Mastodon'=>'Megosztás Mastodonon','Share via email (mailto:)'=>'Megosztás e-mailben (mailto:)','JavaScript-powered actions'=>'JavaScript-alapú műveletek','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Másold a jelenlegi URL-t a vágólapra. Siker esetén megjelenik egy „Link másolva” értesítés.','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Nyissa meg a böngésző natív Web Share lapját (iOS, Android, néhány asztali). Visszalép a vágólap másolására, ha nem támogatott.','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Használja a natív megosztást, ha elérhető; ha nem, másolja a vágólapra. Ajánlott alapértelmezett a "Megosztás" gombokhoz.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'A megosztási URL mindig a jelenlegi oldalt tükrözi — nincs szükség manuális URL-beírásra. A linguaforge_social_share_url szűrő lehetővé teszi, hogy felülírja a feloldott URL-t bármely szolgáltatáshoz.','Configuration issue: WP site language has no content on this site'=>'Konfigurációs hiba: A WP webhely nyelve nem rendelkezik tartalommal ezen az oldalon','The WordPress site language (%1$s) maps to the language code "%2$s", but no posts on this site are tagged _lf_lang=%2$s. This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'A WordPress webhely nyelve (%1$s) a „%2$s" nyelvkódra van leképezve, de ezen a webhelyen egyetlen bejegyzés sem van _lf_lang=%2$s címkével ellátva. Ez azt okozza, hogy a WooCommerce terméklekérdezések nulla eredményt adnak vissza, a termékképek meghibásodnak, és az összes nyelvszűrt tartalomkérdezés megtörik.','Fix: go to'=>'Javítás: menj a','Settings → General → Site Language'=>'Beállítások → Általános → Oldal nyelve','and set it to one of your actual content languages (e.g. %s).'=>'és állítsa be az egyik tényleges tartalmi nyelvére (pl. %s).','Environment'=>'Környezet','Lingua Forge version'=>'Lingua Forge verzió','WordPress version'=>'WordPress verzió','PHP version'=>'PHP verzió','Active theme'=>'Aktív téma','(FSE / block theme)'=>'(FSE / blokk téma)','(classic theme)'=>'(klasszikus téma)','URL structure'=>'URL szerkezet','Subdomain (de.example.com)'=>'Aldomain (de.example.com)','Path prefix (/de/)'=>'Útvonal előtag (/de/)','WP instance language'=>'WP példány nyelve','not a content language — see notice above'=>'nem tartalomnyelv — lásd a fent említett figyelmeztetést','Primary content language'=>'Elsődleges tartalom nyelve','Active languages'=>'Aktív nyelvek','PHP max_execution_time'=>'PHP max_execution_time','No PHP limit'=>'Nincs PHP limit','(server/FPM timeout still applies)'=>'(szerver/FPM időtúllépés még mindig érvényes)','AI translation and batch analysis may time out. Recommend 120s or more.'=>'Az AI fordítás és a kötegelt elemzés időtartama lejárhat. Ajánlott 120 másodperc vagy több.','PHP memory_limit'=>'PHP memory_limit','AI Configuration'=>'AI konfiguráció','(active)'=>'(aktív)','Configured'=>'Beállítva','No key'=>'Nincs kulcs','— AI features are disabled.'=>'— Az AI funkciók le vannak tiltva.','Add key →'=>'Hozzáadás kulcshoz →','Light model'=>'Könnyű modell','Quality model'=>'Minőségi modell','Active preset'=>'Aktív preset','Daily quota'=>'Napi kvóta','Unlimited'=>'Korlátlan','requests / day'=>'kérések / nap','Permalink Structure'=>'Permalink szerkezet','Permalink structure is compatible with Lingua Forge path routing.'=>'A permalink szerkezet kompatibilis a Lingua Forge útvonalirányítással.','Plain permalinks are not supported.'=>'Az egyszerű permalinkek nem támogatottak.','Path routing requires a post-name based permalink structure. Change it in'=>'Az útvonalirányítás post-név alapú permalink szerkezetet igényel. Változtassa meg a','Settings → Permalinks'=>'Beállítások → Permalinks','Numeric permalink structure is not supported.'=>'A numerikus permalink szerkezet nem támogatott.','Switch to a post-name based structure in'=>'Váltás post-név alapú szerkezetre a','SEO Plugins'=>'SEO bővítmények','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'Nem észlelt harmadik fél SEO-bővítmény. A Lingua Forge minden többnyelvű SEO kimenetet kezeli.','Active: %s.'=>'Aktív: %s.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Lásd a Beállítások → SEO → Kompatibilitás menüpontot a teljes funkciók szerint működő táblázathoz.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'A WooCommerce nem aktív.','Shop'=>'Bolt','Cart'=>'Kosár','Checkout'=>'Pénztár','My Account'=>'Fiókom','WooCommerce version'=>'WooCommerce verzió','Order storage'=>'Rendelés tárolás','High-Performance Order Storage (HPOS)'=>'Magas teljesítményű rendelés tárolás (HPOS)','Custom tables — LF post-meta filters do not affect orders.'=>'Egyedi táblák — LF poszt-meta szűrők nem befolyásolják a rendeléseket.','Shared / compatibility mode'=>'Megosztott / kompatibilitási mód','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT szinkronizálva — átmeneti; LF poszt-meta szűrők alkalmazhatók a CPT másolatra.','Legacy post-based (CPT)'=>'Örökség poszt-alapú (CPT)','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'Rendelések a wp_posts-ban — győződjön meg arról, hogy a shop_order ki van zárva az LF útvonalból.','WcPageBridge active'=>'WcPageBridge aktív','Yes'=>'Igen','No — WooCommerce integration class not loaded'=>'Nem — WooCommerce integrációs osztály nincs betöltve','WooCommerce page translations'=>'WooCommerce oldal fordítások','No secondary languages configured.'=>'Nincs konfigurálva másodlagos nyelv.','Active Plugins'=>'Aktív bővítmények','No active plugins detected.'=>'Nem észlelt aktív bővítmények.','Version'=>'Verzió','_lf_lang Coverage'=>'_lf_lang lefedettség','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'A _lf_lang nélküli bejegyzések láthatatlanok minden Lingua Forge nyelvi szűrő számára. Ez akkor fordulhat elő, amikor a tartalmat importálják vagy a bővítményt aktiválás előtt hozták létre.','All published posts have a _lf_lang value. No gaps detected.'=>'Minden közzétett bejegyzés rendelkezik _lf_lang értékkel. Nem észlelhető hiányosság.','Missing'=>'Hiányzik','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'Ezt a poszt típust kizárja a nyelvi routingból — posztjai többé nem jelennek meg itt, vagy nem kapnak _lf_lang értéket. Ez nem vonható vissza automatikusan.','Exclude from routing'=>'Kizárás a routingból','excluded from routing'=>'kizárva a routingból','Destructive action — read before proceeding'=>'Káros művelet — olvassa el, mielőtt folytatná','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'Javítsa a címkéket minden felsorolt útvonalas poszton, _lf_lang = %s. Az útvonalzási kizárt poszt típusokban nem érintett posztok. Csak tartalom importálása vagy első aktiválás után futtassa — ne használja tömeges nyelvváltó eszközként.','Repair — assign _lf_lang = %s to all routable posts above'=>'Javítás — rendeljen _lf_lang = %s értéket minden fent felsorolt útvonalas posztra','Rewrite Rules'=>'Átírási szabályok','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'LF tulajdonában lévő bejegyzések jelenleg regisztrálva vannak a $wp_rewrite->extra_rules_top-ban. Hasznos hibák vagy útvonal konfliktusok diagnosztizálásához. Másolja ezeket hibajelentés benyújtásakor.','%d rule registered'=>'%d szabály regisztrálva' . "\0" . '%d szabály regisztrálva','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'Nem található LF átírási szabály. Törölje a permalinkeket, ha ez váratlan.','Debug Info'=>' Hibakeresési információk','Copy and paste into a GitHub issue or support request.'=>'Másolja és illessze be egy GitHub hibajegybe vagy támogatási kérésbe.','Copy system info'=>'Rendszerinformációk másolása','Copied!'=>'Másolva!','Repairing…'=>'Javítás folyamatban…','Repair failed.'=>'A javítás sikertelen.','Network error.'=>'Hálózati hiba.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'Ezt a poszt típust kizárja a nyelvi routingból? Posztjai többé nem jelennek meg ebben a listában, vagy nem kapnak _lf_lang értéket. Ezt visszavonhatja a Beállítások → Router → Kizárások kérdőívében.','Excluding…'=>'Kizárás…','Failed to save exclusion.'=>'Kizárás mentése sikertelen.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d bejegyzés címkézve _lf_lang = %2$s.' . "\0" . '%1$d bejegyzés címkézve _lf_lang = %2$s.','Uninstall Behaviour'=>'Eltávolítási viselkedés','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Szabályozza, mi történik, amikor egy adminisztrátor eltávolítja a bővítményt a Bővítmények → Telepített bővítmények → Törlés menüpontban. A bővítmény beállításai és az AI gyorsítótárak mindig törlődnek. A nyelvi hozzárendeléseket és a fordítási kapcsolatokat alapértelmezés szerint megtartja, így véletlen eltávolítás vagy újratelepítés esetén ott folytathatja, ahol abbahagyta.','Uninstall setting saved.'=>'Eltávolítási beállítás mentve.','Delete content data on uninstall'=>'Tartalomadatok törlése az eltávolításkor','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Továbbá törli a nyelvi hozzárendeléseket, fordítási kapcsolatokat, meta leírásokat, glosszáriumot és Fordítási Memóriát, amikor a bővítményt eltávolítják.','Warning:'=>'Figyelem:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Ha be van jelölve, a bővítmény eltávolítása véglegesen törli az összes nyelvi hozzárendelést, fordítási kapcsolatot, meta leírást, oldalspecifikus előbeállításokat, az AI glosszáriumot és a Fordítási Memóriát minden bejegyzéshez ezen az oldalon. Ez nem vonható vissza. Hagyja üresen, hacsak nem teljesen távolítja el a többnyelvű támogatást az oldalról.','Save Uninstall Setting'=>'Mentés az eltávolítási beállításokhoz','Today'=>'Ma','Last 7 days'=>'Az elmúlt 7 nap','Last 30 days'=>'Az elmúlt 30 nap','All time'=>'Összes idő','AI Usage'=>'AI használat','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'A token fogyasztás összesítve funkció, szolgáltató és modell szerint. Minden sikeres AI-hívásnál rögzítve; a Teszt kapcsolat pingszámokat kizárjuk, hogy ne torzítsák az összesítést.','Check your account, billing, or remaining credits directly on the provider console:'=>'Ellenőrizze fiókját, számlázását vagy hátralévő krediteit közvetlenül a szolgáltató konzolján:','Anthropic Console'=>'Anthropic Console','OpenAI Platform'=>'OpenAI Platform','Google AI Studio'=>'Google AI Studio','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Még nem rögzített AI használat. Amint egy szerkesztő fordítást futtat, meta leírást generál, vagy bármilyen más AI funkciót használ, az összesítések itt jelennek meg.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Nincs AI használat a kiválasztott ablakban (%s). Válasszon szélesebb időintervallumot fent.','Provider'=>'Szolgáltató','Model'=>'Modell','Requests'=>'Kérések','Input tokens'=>'Bemeneti tokenek','Output tokens'=>'Kimeneti tokenek','Total tokens'=>'Összes token','Total'=>'Összes','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'A Lingua Forge WooCommerce-specifikus Open Graph tulajdonságokat ad hozzá a termékoldalakhoz, így a termék URL megosztásakor Facebookon, Pinteresten és hasonló platformokon a helyes terméktípus, ár és elérhetőség jelenik meg.','WooCommerce SEO settings saved.'=>'WooCommerce SEO beállításokat elmentettük.','Product Open Graph'=>'Termék Open Graph','Add WooCommerce product tags to Open Graph output'=>'WooCommerce termék címkék hozzáadása az Open Graph kimenethez.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Amikor engedélyezve van, a Lingua Forge a termékoldalakon a következő meta címkéket adja hozzá: og:type=product, og:price:amount, og:price:currency, og:availability, és azok a Facebook Catalog által használt product: névtér szerinti megfelelőik.','Tags emitted'=>'Kibocsátott címkék','Tag'=>'Címke','Value source'=>'Érték forrása','"product" (replaces "article")'=>'„termék” (helyettesíti az „cikket”)','WooCommerce product price'=>'WooCommerce termékár','WooCommerce store currency'=>'WooCommerce bolt pénzneme','instock / oos / pending from WC stock status'=>'készleten / elfogyott / függőben a WC készlet státusza szerint','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Az ár és a rendelkezésre állás mindig a forrásnyelvi terméket tükrözi (megosztott készlet modell). A címkék csak akkor jelennek meg, ha az LF Open Graph modulja "Teljes" vagy "Automatikus" módban van, és nem észlelhető ütköző SEO plugin.','Save WooCommerce SEO Settings'=>'WooCommerce SEO beállítások mentése','AI Provider'=>'AI Szolgáltató','AI Usage & Cache'=>'AI Használat & Gyorsítótár.','API Keys'=>'API kulcsok','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'A kulcsokat AES-256-CBC titkosítással tárolják a WordPress adatbázisban. A titkosítás titkos kulcsa a WordPress hitelesítési sóiból származik (wp-config.php), így a tiszta szövegű kulcsok soha nem kerülnek az adatbázisba.','API credentials are managed by WordPress in %s. No key is stored by Lingua Forge.'=>'Az API-hitelesítő adatokat a WordPress kezeli a %s oldalon. A Lingua Forge nem tárol kulcsot.','Settings → Connectors'=>'Beállítások → Összekötők','API Key'=>'API kulcs','Paste your API key…'=>'Illessze be az API kulcsát…','✓ Configured'=>'✓ Beállítva','✗ Not configured'=>'✗ Nincs beállítva','Test connection'=>'Kapcsolat tesztelése','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Hagyja üresen, hogy megtartsa a meglévő kulcsot. Adjon meg egy új értéket a helyettesítéshez.','Remove stored key'=>'Tárolt kulcs eltávolítása','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Ez a kulcs jelenleg egy szerver által biztosított %s, és nem távolítható el itt. Adjon meg egy új kulcsot fent, hogy felülírja az adatbázis értékével.','environment variable'=>'környezeti változó','PHP constant'=>'PHP állandó','Alternative (server-side):'=>'Alternatív (szerver oldali):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Kulcsokat állandóként vagy környezeti változóként is definiálhat (pl. wp-config.php-ban). Ezek a források automatikusan használatba kerülnek, ha nincs adatbázisban tárolt kulcs.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Egyedi titkosítási titok használatához (a származtatott wp_salt helyett), adja hozzá ezt a wp-config.php-hoz:','Unknown provider.'=>'Ismeretlen szolgáltató.','No API key configured for this provider.'=>'Nincs API kulcs konfigurálva ehhez a szolgáltatóhoz.','Could not instantiate the provider.'=>'Nem sikerült példányosítani a szolgáltatót.','Provider returned no response. Check the WordPress error log for details.'=>'A szolgáltató nem adott választ. Ellenőrizze a WordPress hibajegyzéket a részletekért.','Enter a model identifier to test.'=>'Adjon meg egy modell-azonosítót a teszthez.','No published post or page found to test with — publish some content first, or try Quick Translate directly.'=>'Nincs közzétett bejegyzés vagy oldal a teszteléshez — először közzétegyen valamilyen tartalmat, vagy próbálja ki a Gyors fordítást közvetlenül.','(untitled)'=>'(cím nélkül)','Prompt template not found.'=>'Promptsablon nem található.','Translation failed. Please try again.'=>'A fordítás nem sikerült. Próbálja meg újra.','The sample post has no visible text content to translate.'=>'A mintabejegyzésnek nincs látható szöveges tartalma a fordításhoz.','Chunk prompt template not found.'=>'Chunk prompt sablon nem található.','Model returned no response. Check the WordPress error log for details.'=>'A modell nem adott vissza választ. További részletekért ellenőrizze a WordPress-hibanapló.','Behavior'=>'Viselkedés','Block Editor'=>'Blokk szerkesztő','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'A Lingua Forge alapértelmezés szerint két Gutenberg funkciót korlátoz, hogy az szerkesztési viselkedés egységes maradjon a nyelvek között. Itt választhat, ha teljes Gutenberg / FSE képességekre van szüksége.','Block locking'=>'Blokk zárolása','Allow editors to lock individual blocks'=>'Engedélyezi a szerkesztőknek az egyes blokkok zárolását','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Újra engedélyezi Gutenberg canLockBlocks funkcióját. Hasznos szerkesztői sablonokhoz, amelyek megakadályozzák a hozzájárulók számára, hogy bizonyos blokkokat mozgatni vagy törölni tudjanak.','Template mode'=>'Sablon mód','Allow Gutenberg template-editing mode on post screens'=>'Engedélyezi a Gutenberg sablon szerkesztési módját a bejegyzés képernyőin','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Újra engedélyezi a supportsTemplateMode funkciót. Alapvető a teljes webhely szerkesztési munkafolyamatokban, ahol szándékosan vannak bejegyzés szintű sablon felülírások.','Compliance Preset'=>'Megfelelőségi előbeállítás','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Szigorú megőrzési mód jogi, szabályozási, orvosi vagy technikai tartalomhoz. Amikor be van kapcsolva, minden AI funkció alacsony mintavételi hőmérsékletet használ, és a rendszer kéréséhez hozzáfűzi az alábbi kiegészítést — a terminológia, cikk számok, egységek, márkanevek és szabályozási nyelv szó szerint megőrzött, nem parafrazált.','Global AI preset'=>'Globális AI előbeállítás','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, funkciónként','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Beállítja az alapértelmezett AI viselkedést az összes funkcióhoz az oldal egészén. Egyes bejegyzések felülírhatják ezt a Fordítás és Tartalom Generálás esetén a Lingua Forge meta dobozban.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'A Standard minden funkció saját hangolt hőmérsékletet használ: Fordítás T=0.2 (pontos), Gyors fordítás T=0.4, Tartalom generátor T=0.6 (kreatív). A többi előbeállítás egységesen alkalmaz egy fix hőmérsékletet minden funkciónál.','Technical / Scientific instructions'=>'Technikai / Tudományos utasítások','Legal / Compliance instructions'=>'Jogi / Megfelelőségi utasítások','Creative / Marketing instructions'=>'Kreatív / Marketing utasítások','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Hagyja üresen az alapértelmezett használatához. A mentett felülírás törlése a következő mentéskor visszaállítja az alapértelmezettet.','View built-in default'=>'Alapértelmezett megtekintése','Automatic Translation Backfill'=>'Automatikus fordítás kitöltése','Periodically scans for posts missing a translation in an active language and queues an AI translation for each gap found — the same recovery you can already trigger by hand via "Translate missing" or the WP-CLI missing_translations/fill_translations commands, run automatically once an hour instead.'=>'Periodikusan megkeresi azokat a bejegyzéseket, amelyekből hiányzik egy fordítás egy aktív nyelven, és mesterséges intelligencia fordítást sorol fel az egyes hiányosságokhoz — ugyanez a helyreállítás, amelyet már manuálisan indíthat a "Hiányzó fordítások" vagy a WP-CLI missing_translations/fill_translations parancsok segítségével, automatikusan és óránként futtatva.','Automatic backfill'=>'Automatikus kitöltés','Automatically translate posts missing a language version'=>'Automatikusan fordítsa le a hiányzó nyelvű bejegyzéseket','Off by default. This feature makes AI provider requests — and spends the associated API cost — automatically and in the background, with no per-request confirmation, for every published post found without a translation in an active language. Turn this on only if you want every content gap translated unattended; otherwise use "Translate missing" or the WP-CLI commands to translate on your own schedule.'=>'Alapértelmezés szerint ki van kapcsolva. Ez a funkció mesterséges intelligencia szolgáltató kéréseket — és a hozzájuk kapcsolódó API költségeket — automatikusan és a háttérben, kérésenkénti megerősítés nélkül, az aktív nyelvből hiányzó fordítások nélküli minden közzétett bejegyzéshez használ fel. Csak akkor kapcsolja be, ha azt szeretné, hogy minden tartalomhiány fordítva legyen felügyelet nélkül; ellenkező esetben a WP-CLI parancsokkal fordítson saját ütemezés szerint.','WooCommerce products and variations are never included, regardless of this setting. An integration can also block specific post types via the linguaforge_cpt_create_allowed filter.'=>'A WooCommerce termékek és variációk soha nem kerülnek be, függetlenül ettől a beállítástól. Az integráció az linguaforge_cpt_create_allowed szűrő segítségével blokkol adott bejegyzéstípusokat.','The "Sync" button in the post list Lang column retranslates a post out into every other language, including the primary/source post when it\'s run from a translation. That back-translation direction is restricted by default for every post type. (WooCommerce products and variations have their own separate setting below — this one does not affect them.)'=>'A bejegyzéslista Lang oszlopában található "Szinkronizálás" gomb újra lefordít egy bejegyzést az összes többi nyelvre, beleértve az elsődleges/forrásbejegyzést is, ha egy fordításból futtatják. Ez a vissza-fordítási irány alapértelmezés szerint korlátozott minden bejegyzéstípusnál. (A WooCommerce termékeknek és variációknak saját külön beállítása van alább — ez nem érinti őket.)','Secondary-language Sync'=>'Másodlagos nyelvű szinkronizálás','Allow "Sync" on a translated post to overwrite the primary post'=>'Engedélyezze a "Szinkronizálás" lehetőséget egy fordított bejegyzésen az elsődleges bejegyzés felülírásához','Off by default: clicking "Sync" on a translation is blocked from overwriting the primary post. Syncing FROM the primary post to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Alapértelmezés szerint ki van kapcsolva: egy fordítás "Szinkronizálása" blokkolva van az elsődleges bejegyzés felülírásától. A szinkronizálás az elsődleges bejegyzésből az összes fordításra mindig engedélyezett, függetlenül ettől a beállítástól. Csak akkor kapcsolja be, ha szándékosan azt szeretné, hogy egy fordítás legyen az új forrástartalomma.','The primary-language product is WooCommerce\'s operational source of truth for price, SKU, and stock, which are always served from it regardless of which language a shopper is viewing. This is a separate, independent setting from the general "Sync" restriction above — enabling one does not enable the other.'=>'Az elsődleges nyelvű termék a WooCommerce működési igazság forrása az árra, az SKU-ra és a készletre, amelyeket mindig az elsődleges termékről szolgáltatnak, függetlenül attól, hogy a vásárló melyik nyelvet nézi. Ez egy külön, független beállítás az általános "Szinkronizálás" korlátozástól — az egyik engedélyezése nem engedélyezi a másikat.','Allow "Sync" on a translated product to overwrite the primary product'=>'Engedélyezze a "Szinkronizálás" lehetőséget egy fordított terméken az elsődleges termék felülírásához','Off by default: clicking "Sync" on a translated WooCommerce product is blocked, since it would back-translate onto the primary product\'s title, description, and excerpt. Syncing FROM the primary product to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Alapértelmezés szerint ki van kapcsolva: egy lefordított WooCommerce termék "Szinkronizálása" blokkolva van, mivel az elsődleges termék címe, leírása és kivonatára vissza-fordítana. A szinkronizálás az elsődleges termékből az összes fordításra mindig engedélyezett, függetlenül ettől a beállítástól. Csak akkor kapcsolja be, ha szándékosan azt szeretné, hogy egy fordítás legyen az új forrástartalomma.','General'=>'Általános','Light'=>'Könnyű','Meta Description, Excerpt Generator, quick translate'=>'Meta leírás, kivonat generátor, gyors fordítás','Quality'=>'Minőség','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'Teljes oldal fordítás, Tartalom generátor (közepes szintű modellek teljesen elegendőek)','Active Provider'=>'Aktív szolgáltató','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Jelenleg az %s állandóból öröklött. Egy érték megadása itt felülírja azt.','WordPress AI Client — requirements:'=>'WordPress AI kliens — követelmények:','Full-page translation uses JSON-schema-constrained output. This requires a connector plugin to be installed and active (not just an API key saved in Settings → Connectors). If translation fails, check the PHP error log for the specific error, or switch to a built-in provider.'=>'A teljes oldal fordítása JSON-séma-korlátozott kimenetet használ. Ehhez egy csatlakozó bővítmény telepítése és aktiválása szükséges (nem csak egy API-kulcs mentése a Beállítások → Csatlakozók menüben). Ha a fordítás sikertelen, ellenőrizze a PHP hibajegyzéket a konkrét hibáért, vagy válassza a beépített szolgáltatót.','Manage your account, review usage, or top up credits:'=>'Fiók kezelése, használat áttekintése, vagy kreditek feltöltése:','WordPress Connectors'=>'WordPress Csatlakozók','Models'=>'Modellek','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'A funkciók két szintbe vannak csoportosítva. Adja meg pontosan az egyes szintek és szolgáltatók modell azonosítóját. Hagyjon üresen egy mezőt, hogy a beépített alapértelmezést használja (amelyet helykitöltőként mutatunk). Csak az aktív szolgáltató modelljei hívódnak meg futásidőben — a többit előre konfigurálja, ha váltani kíván.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'Írjon be bármely mezőbe, hogy modell javaslatokat lásson, vagy használja az alábbi referencia táblát. A könnyű és középszintű minőségű modellek (Haiku, GPT-4o mini, Gemini Flash) teljesen elegendőek fordításhoz és tartalomgeneráláshoz — a zászlóshajó "max" modellek költséget adnak hozzá minimális minőségjavulással a strukturált szöveghez.','active'=>'aktív','Model selection is managed by WordPress in %s — no model identifier is stored by Lingua Forge for this provider.'=>'A modell kiválasztását a WordPress kezeli a %s oldalon — a Lingua Forge nem tárol modellazonosítót ehhez a szolgáltatáshoz.','overridden'=>'felülírt','Translates a short sample of your most recent published post with this exact model — a real, billed API call.'=>'Rövid mintát fordít le a legtöbb közelmúltbeli közzétett bejegyzésből ezzel a pontos modellel — egy valódi, számlázott API hívás.','Test model'=>'Modell tesztelése','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tipp: a modell visszaállításához az alapértelmezett értékre, törölje a mezőt és mentse.','Available models reference'=>'Elérhető modellek referencia','Model ID'=>'Modell azonosító','Name'=>'Név','Tier'=>'Szint','Notes'=>'Megjegyzések','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'Ez a katalógus minden Lingua Forge kiadással frissül. A kapcsolat tesztelése az API kulcsok fülön keresztül szintén lekéri a szolgáltató élő modell listáját és frissíti a fenti javaslatokat.','Glossary'=>'Szójegyzék','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Felhasználó által kezelt terminológia táblázat nyelvpár szerint. Bejegyzéseket adunk hozzá a fordítási rendszerhez, így az AI következetesen használja a preferált kifejezéseket — kritikus a szakterületi szókincshez ("kWp", "PPA", "összekötő pont"), márkanevekhez, amelyeket nem szabad fordítani, és szabványosított szabályozási kifejezésekhez. Mindkét nyelvi mező opcionális: hagyja üresen a "Forrás nyelv" mezőt, hogy a bejegyzést bármely nyelvről fordítva alkalmazza; hagyja üresen a "Cél nyelv" mezőt, hogy az összes célnyelvre alkalmazza egyszerre.','Glossary entry added.'=>'Szójegyzék bejegyzés hozzáadva.','Glossary entry removed.'=>'Szójegyzék bejegyzés eltávolítva.','Could not add entry: source term and target term are required.'=>'Nem sikerült hozzáadni a bejegyzést: szükséges a forrás és a cél kifejezés.','Could not save the glossary entry.'=>'Nem sikerült elmenteni a szójegyzék bejegyzést.','Source language'=>'Forrás nyelv','— Any —'=>'— Bármely —','Target language'=>'Cél nyelv','— Any target —'=>'— Bármely cél —','Filter'=>'Szűrő','Reset'=>'Visszaállítás','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Jelenleg nincs egyező szójegyzék bejegyzés a szűrővel. Törölje a szűrőt, hogy minden bejegyzést lásson, vagy adjon hozzá újat az alábbiakban.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Még nincs szójegyzék bejegyzés. Adjon hozzá egyet az alábbiakban, hogy elkezdje a terminológia érvényesítését a fordításokban.','Source term'=>'Forrás kifejezés','Target term'=>'Cél kifejezés','Source lang'=>'Forrás nyelv','Target lang'=>'Cél nyelv','any'=>'bármilyen','Delete this glossary entry?'=>'Törli ezt a szójegyzék bejegyzést?','Add new entry'=>'Új bejegyzés hozzáadása','The phrase as it appears in the source text.'=>'A kifejezés, ahogyan a forrásszövegben megjelenik.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Hogyan kell megjelennie a fordításban. Írja be ugyanazt az értéket, mint a forrás kifejezés, hogy az AI megőrizze szó szerint.','— Any source language —'=>'— Bármely forrás nyelv —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Hagyja üresen a márkanevek és nyelvfüggetlen kifejezések esetében, amelyeket minden fordításban meg kell tartani.','— Any target language —'=>'— Bármely cél nyelv —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Hagyja üresen, hogy ezt a bejegyzést minden célnyelvre alkalmazza — ideális márkanevekhez, rövidítésekhez és olyan kifejezésekhez, amelyeket szó szerint meg kell tartani minden fordításban.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Opcionális kontextus szerkesztők számára (pl. "ASIC = Application-Specific Integrated Circuit; megőrizni angolul technikai kontextusban").','Add entry'=>'Bejegyzés hozzáadása','Limits'=>'Határok','Authors and above (edit_published_posts)'=>'Szerzők és felette (szerkeszt_publikált_bejegyzések)','Contributors and above — default (edit_posts)'=>'Hozzájárulók és felette — alapértelmezett (szerkesztés_bejegyzések)','Editors and above (edit_others_posts)'=>'Szerkesztők és felette (szerkeszt_others_posts)','Administrators only (manage_options)'=>'Csak rendszergazdák (manage_options)','AI Limits & Security'=>'AI Határok és Biztonság','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Korlátozza, mennyit használhat az oldal AI-t, és korlátozza, mely felhasználói szerepkörök indíthatnak fizetős AI hívásokat. Ez a felhasználónkénti díjszabás (30 kérés / perc, beégetve) fölött helyezkedik el, amely már védi az egy felhasználótól származó futó ciklusokat.','Daily request limit'=>'Napi kéréslimit','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Az oldal egészére vonatkozó plafon az AI kérésre UTC nap szerint (mind a Toolbar fordításokat, mind a blokk módosításokat számítva). A számláló UTC éjfélkor nullázódik. Állítsa 0-ra a letiltáshoz.','Minimum role'=>'Minimum szerepkör','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'A legalacsonyabb WordPress képesség, amely lehetővé teszi az AI funkciók indítását. Ennek szigorítása több szerzős oldalakon megakadályozza, hogy a Hozzájárulók vagy próbafiókok fizetős AI hívásokat futtassanak. Felülírható az egyes funkciók esetében a linguaforge_required_capability szűrő segítségével.','Translation Limits'=>'Fordítási Határok','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Szabályozza, mennyi tartalmat küld az AI-nak, és mekkora lehet a válasz. Hagyja üresen a mezőt, hogy a beépített alapértelmezést használja (helykitöltőként mutatva). Növelje ezeket az értékeket, ha nagy oldalakat vágnak le; csökkentse őket az API költségek csökkentése érdekében.','Model tier'=>'Modell szint','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Minőség (alapértelmezett — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Könnyű (gyors és költséghatékony — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Melyik modell szintet használja a teljes oldal fordításához. A minőség a fent felsorolt Modellek táblában beállított modellt használja, és ajánlott pontos, hosszabb formátumú fordításokhoz. Csak akkor váltson Könnyűre, ha a sebesség vagy a költség a prioritás, és a tartalom rövid.','Max output tokens'=>'Maximális kimeneti tokenek','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'A maximális tokenek száma, amelyet az AI egy fordítási válaszban előállíthat. Ha a fordítás csendben megszakad a végén, növelje ezt az értéket. Alapértelmezett: 16 000.','Max input characters'=>'Maximális bemeneti karakterek','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maximum számú karakter a poszt tartalmából, amit az AI-hoz továbbítanak. 0 azt jelenti, hogy nincs korlátozás — a teljes tartalom mindig elküldésre kerül (ajánlott). Állítson be nem nulla értéket csak akkor, ha a szolgáltatója szigorú kontextusablakkal rendelkezik. Figyelmeztetés kerül kiírásra a PHP hibajegyzékbe, amikor a tartalmat levágják.','Quick Translation'=>'Gyors fordítás','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'A Gyors fordítás a snippet/chunk módban használható — rövid szakaszok fordítása kérésre az eszköztárról, szerkesztőről vagy blokk felugró ablakokból. Külön, könnyebb konfigurációt használ a teljes oldal fordításától, hogy a válaszok gyorsak és költséghatékonyak maradjanak.','Light (default — fast and cost-effective)'=>'Könnyű (alapértelmezett — gyors és költséghatékony)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Minőség (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'A Könnyű szint a gyors modellt használja, amely a fent említett Modellek táblában van konfigurálva (alapértelmezett: Haiku / Flash). Válts a Minőségre, ha ugyanazt a fordítási pontosságot szeretnéd elérni, mint a teljes oldal módban a snippet-ekhez.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'A maximális tokenek száma, amit az AI generálhat gyors fordításonként. Alapértelmezett: 2000.','Maximum characters accepted from the input field. Default: 8 000.'=>'A bemeneti mezőből elfogadott maximális karakterek száma. Alapértelmezett: 8000.','Content Generator'=>'Tartalom Generátor','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Szabályozza az AI Tartalom Generátor funkció token költségvetését és bemeneti korlátait. Hagyja üresen a mezőket az alapértelmezett beállítások használatához.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'A maximális tokenek száma, amit az AI generálhat egy generálási futás során. Növelje, ha a teljes cikkek levágódnak. Alapértelmezett: 8192.','Max hints characters'=>'Max. tipp karakterek','Maximum characters read from the Hints field. Default: 2 000.'=>'A Hint mezőből olvasott maximális karakterek száma. Alapértelmezett: 2000.','Max context characters'=>'Max. kontextus karakterek','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'A meglévő poszt tartalmának maximális karakterei, amelyeket az AI seed kontextusként kap, ha nem ad meg Hint-et. Alapértelmezett: 6000.','Maintenance'=>'Karbantartás','Router'=>'Útválasztó','Primary language saved.'=>'Elsődleges nyelv mentve.','Permalink rules flushed successfully.'=>'Permalink szabályok sikeresen ürítve.','Language uninstalled. %d post deleted.'=>'Nyelv eltávolítva. %d bejegyzés törölve.' . "\0" . 'Nyelv eltávolítva. %d bejegyzés törölve.','%d locale file removed.'=>'%d nyelvi fájl törölve.' . "\0" . '%d nyelvi fájlok törölve.','%d pattern translation removed.'=>'%d mintafordítás eltávolítva.' . "\0" . '%d mintafordítás eltávolítva.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d nyelvi fájl nem törölhető automatikusan (DISALLOW_FILE_MODS be van állítva). Töröld manuálisan a szervered vagy a WP-CLI segítségével: wp language core uninstall <locale>.' . "\0" . '%d nyelvi fájl nem törölhető automatikusan (DISALLOW_FILE_MODS be van állítva). Töröld manuálisan a szervered vagy a WP-CLI segítségével: wp language core uninstall <locale>.','Primary Language'=>'Elsődleges nyelv','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Az elsődleges nyelvet mindig a webhely gyökérben szolgálja ki — nincs URL előtag útvonal módban, nincs nyelvi aldomain al-módban. Minden más nyelv vagy a /lang/ útvonal előtagot (pl. example.com/de/) vagy nyelvi aldomaint (pl. de.example.com) használ, az alábbi URL-struktúra beállítástól függően.','Primary language'=>'Elsődleges nyelv','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Az elsődleges nyelv megváltoztatása után ürítse ki a permalinkeket (az alábbi szakaszban), hogy frissüljön az URL irányítás.','Path prefix — example.com/de/'=>'Útvonal előtag — example.com/de/','Subdomain — de.example.com/'=>'Aldomain — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Az aldomain módja megköveteli, hogy a webkiszolgálód minden nyelvi aldomaint (pl. de.example.com) erre a WordPress telepítésre mutasson. A módváltás után ürítsd ki a permalink szabályokat és töröld a cache-eket. Ha a fő URL tartalmazza a www-t (pl. www.example.com), használd az lf_base_domain szűrőt az egyszerű csúcs domain beállításához, hogy az aldomének helyesen legyenek kialakítva.','Browser language redirect'=>'Böngésző nyelvi átirányítás','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Átirányítja a látogatókat a böngésző Accept-Language fejléc alapján a preferált nyelvükre','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Amikor engedélyezve van, az első alkalommal látogatók, akiknek nincs nyelvi sütiük és nincs nyelvi előtag a URL-ben, a legközelebbi egyező nyelvi verzióra lesznek átirányítva. Az átirányítás kihagyásra kerül, ha a böngésző preferált nyelve nem az aktív router nyelvek között van. Miután a látogató kiválaszt egy nyelvet a váltó segítségével, a süti felülírja, és a böngésző fejlécét minden jövőbeni látogatásnál figyelmen kívül hagyják.','Query Filter Exclusions'=>'Lekérdezés szűrő kizárások','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'A Lingua Forge a másodlagos WP_Query példányokat (oldalsáv widgetek, sablon blokkok, plugin keresések) az aktív nyelvre szűri egy _lf_lang meta korlátozás beillesztésével. A listázott poszt típusok itt nem szerepelnek ebben a korlátozásban — kérdéseik mindig szűretlenek.','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'A Contact Form 7 (wpcf7_contact_form), Flamingo kapcsolatok és bejövő üzenetek (flamingo_contact, flamingo_inbound), valamint a WordPress nyelvi csomag szinkron tárolása (wp_sync_storage) automatikusan kizárásra kerül. Adj hozzá más harmadik fél által készített bejegyzéstípusokat, amelyek tartalmát nem kell nyelvi szűrővel kezelni, egy sorban vagy vesszővel elválasztva.','Excluded post types'=>'Kizárt poszt típusok','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'Poszt típus slugok vesszőkkel vagy új sorokkal elválasztva. A változtatások azonnal érvénybe lépnek mentéskor — nincs szükség permalink frissítésre.','WooCommerce Integration'=>'WooCommerce integráció','Controls how Lingua Forge integrates with WooCommerce order processing.'=>'Szabályozza, hogyan integrálódik a Lingua Forge a WooCommerce rendelésfeldolgozásába.','Order line item source mapping'=>'Megrendelés soronkénti forrás hozzárendelése','Normalize order line item product IDs to the source-language product at checkout'=>'A megrendelés soronkénti termékazonosítókat normalizálja a forrásnyelvi termékre a fizetésnél','When enabled (recommended), the product ID stored on each WooCommerce order line item is set to the source-language product. This ensures total_sales counts, WC Analytics revenue rows, and third-party ERP exports reference one product ID per SKU rather than one per language version. Trade-off: "View product" links in order emails and My Account lead to the source-language page. Disable only if a connected system relies on translated product IDs in orders. Use the linguaforge_wc_order_item_source_mapping filter for per-item overrides.'=>'Amikor engedélyezve van (ajánlott), minden WooCommerce rendelés sorában tárolt termékazonosító a forrásnyelvi termékre van állítva. Ez biztosítja a teljes értékesítés számlálásokat, a WC Analytics bevételi sorokat, és a harmadik fél ERP exportokat, hogy egy termékazonosítót referencia minden SKU-hoz, nem nyelvi verzióként. Kölcsönhatás: a "Termék megtekintése" linkek a rendelés e-mailjeiben és a Saját fiókban a forrásnyelvi oldalra mutatnak. Csak akkor kapcsolja ki, ha egy csatlakoztatott rendszer a fordított termékazonosítókra támaszkodik a rendelésekben. Használja a linguaforge_wc_order_item_source_mapping szűrőt az egyes tételek felülbírálásához.','Save Router Settings'=>'Router beállítások mentése','Flush Permalinks'=>'Permalinkek ürítése','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Újra generálja a WordPress átírási szabályokat, így az URL előtagok, nyelvspecifikus slugok és archívum átírások összhangban lesznek. Szükséges a fő nyelv megváltoztatása vagy új nyelvi támogatás hozzáadása után.','Flush Permalink Rules'=>'Permalink szabályok ürítése','Active Languages'=>'Aktív nyelvek','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'A router által jelenleg ismert nyelvek (a telepített WordPress helyi csomagokból és a fő nyelvből származnak). Telepíts további nyelvi csomagokat az alábbi szakaszban, hogy több nyelvet tegyél elérhetővé az útválasztáshoz és fordításhoz.','%d locale pack installed.'=>'%d helyi csomag telepítve.' . "\0" . '%d helyi csomag telepítve.','Install a Language'=>'Nyelv telepítése','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Töltsd le és telepítsd a WordPress magnyelvi csomagot közvetlenül a WordPress.org-ról. A telepítés után a helyi nyelv elérhető lesz az URL útválasztáshoz és az AI fordítási munkafolyamathoz. A rendelkezésre álló nyelvek listája igény szerint frissül — kattints az alábbi gombra a betöltéshez.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'A nyelvi telepítés le van tiltva ezen a szerveren. A DISALLOW_FILE_MODS állandó beállítás van a wp-config.php fájlban. Telepíts nyelvi csomagokat manuálisan WP-CLI segítségével: wp language core install de_DE','Load available languages'=>'Töltsd be az elérhető nyelveket','— select a language —'=>'— válassz egy nyelvet —','Install'=>'Telepítés','Language Setup'=>'Nyelvi beállítás','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Nincs másodlagos nyelv konfigurálva. Telepíts egy nyelvi csomagot fent, hogy engedélyezd a sablon vázlatokat.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Válassz egy nyelvet a FSE sablonok, sablonrészek és navigációs menük kezeléséhez.','Recreate All Languages'=>'Az összes nyelv újbóli létrehozása','Recreate All Languages (Templates Only)'=>'Az összes nyelv újbóli létrehozása (csak sablonok)','Recreate All Languages (Template Parts Only)'=>'Az összes nyelv újbóli létrehozása (csak sablon részek)','Cancel'=>'Mégse','Repair Template Metadata'=>'Sablon metaadatok javítása','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'Javítja a Site Editor névteret és a _lf_lang címkét az összes LF által létrehozott FSE sablonon, amely az adatbázisban tárolódik. Egyszer futtasd le frissítés után egy korábbi Lingua Forge verzióról — ez áthelyezi a WooCommerce származék sablonokat az aktív téma csoportból a WooCommerce csoportba a Site Editorban, és biztosítja, hogy minden scaffoldelt sablon felfedezhető legyen a lefedettségi jelentések által.','Repair template metadata'=>'Sablon metaadatok javítása','Request failed.'=>'A kérés nem sikerült.','Forbidden'=>'Tiltott','Danger Zone'=>'Veszélyzóna','Uninstall %s'=>'Távolítsa el %s','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Állandóan törli az összes sablont, sablonrészt, mintát, navigációs menüt, bejegyzést, oldalt, egyedi bejegyzéstípust, terméket és termékváltozatot, amelyek ehhez a nyelvhez tartoznak. Eltávolítja a WordPress helyi csomag fájljait is, így ez a nyelv többé nem jelenik meg az útválasztóban. Ez a művelet nem vonható vissza.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Ez a nyelv megfelel a WordPress példány helyi beállításának, és nem távolítható el.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Állandóan eltávolítja a %s nyelvet? Ez törli az összes fordított tartalmat ehhez a nyelvhez, és nem vonható vissza.','Invalid language code.'=>'Érvénytelen nyelvi kód.','This language is protected and cannot be uninstalled.'=>'Ez a nyelv védett, és nem távolítható el.','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'A nyelvi telepítés le van tiltva ezen a szerveren (DISALLOW_FILE_MODS van beállítva).','Invalid locale code.'=>'Érvénytelen helyi kód.','Language %s installed successfully.'=>'A %s nyelv sikeresen telepítve.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'A nyelvi csomag telepítése sikertelen. A nyelv már telepítve lehet, a helyi kód helytelen lehet, vagy a szervered blokkolja a fájlírást.','Navigations'=>'Navigációk','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'A navigáció fordításához aktív AI szolgáltató szükséges. Állíts be API kulcsot az API kulcsok fülön.','Navigation'=>'Navigáció','Re-translate'=>'Újrafordítás','CPT Block Patterns'=>'CPT blokk minták','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'A saját bejegyzéstípusokra regisztrált blokk minták. Használd a Fordítás gombot egy nyelvi változat létrehozásához. A fordított tartalom itt van mentve, és másolható bármely CPT bejegyzésbe a blokk szerkesztő mintabehelyezőből vagy használható kiindulópontként egy Szinkronizált minta (Újrahasznosítható blokk) számára.','Pattern'=>'Minta','Post Types'=>'Bejegyzéstípusok','✓ Translation saved'=>'✓ Fordítás mentve','View'=>'Nézet','Template Parts'=>'Sablonrészek','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'A téma nyelvspecifikus példányai. Miután felépült, a sablonokat frissítik, hogy hivatkozzanak a nyelvspecifikus részre.','Re-create all'=>'Összes újbóli létrehozása','Translate all'=>'Összes fordítása','Fix all links'=>'Minden link javítása','Fix all navs'=>'Összes navigáció javítása','Part'=>'Rész','Status / Actions'=>'Állapot / Akciók','Create'=>'Létrehozás','Templates'=>'Sablonok','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Az aktív téma által elindított FSE sablonok. Hozd létre, majd testreszabhatod a Webhely Szerkesztőben.','Create missing'=>'Létrehozás hiányzik','Fix all parts'=>'Minden rész javítása','SEO'=>'SEO','Multilingual SEO'=>'Többnyelvű SEO','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Hreflang, Open Graph, Schema.org, oldaltérképek és közösségi megosztás konfigurálása minden nyelven az oldaladon. Az alábbi szekciók egy-egy aspektusát kezelik a többnyelvű SEO-nak.','Open Graph &amp; Twitter Cards'=>'Open Graph & Twitter-kártyák','Schema.org'=>'Schema.org','Sitemap'=>'Oldaltérkép','Analysis'=>'Elemzés.','Compatibility'=>'Kompatibilitás.','System'=>'Rendszer','Overview'=>'Áttekintés','Lingua Forge Settings'=>'Lingua Forge beállítások','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'A Lingua Forge többnyelvű irányítást, AI-alapú fordítást, hreflang SEO címkéket és nyelvváltót ad a WordPress oldalához.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Használja a lapfüleket az oldal tetején a konfigurációhoz. A Router fül módosításai azonnal érvénybe lépnek; az AI kulcsok és modell beállítások a következő AI kérésre alkalmazódnak.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Miután megváltoztatta az URL-struktúra beállításait (útvonal előtag ↔ aldomain), mindig látogassa meg a Beállítások → Állandó linkek menüpontot, és kattintson a Mentés gombra az átírási szabályok ürítéséhez.','AI Provider Tab'=>'AI Szolgáltató fül','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'Támogatott szolgáltatók: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Válassza ki az aktív szolgáltatót a legördülőből — egyszerre csak egy szolgáltató van használatban. Adjon meg API kulcsot az adott szolgáltatóhoz az AI funkciók engedélyezéséhez.','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'A kulcsokat nyugalmi állapotban AES-256-GCM titkosítással tárolják, egy oldal-specifikus titkos kulccsal (LINGUAFORGE_SECRET). Ne ossza meg az adatbázis exportokat anélkül, hogy előtte meg nem rotálja a titkos kulcsot.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Az AI funkciók opcionálisak. A nyelvi irányítás, hreflang, a nyelvváltó és a fordítási csoport rendszer mind működik, ha nincs beállítva szolgáltató.','Model tiers'=>'Modell szintek','Lingua Forge uses two model tiers per provider:'=>'A Lingua Forge két modell szintet használ szolgáltatónként:','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Fény: meta leírások és kivonatok generálására — gyors, alacsony költségű.','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Minőség: a bejegyzés fordítására és tartalomgenerálásra használva — magasabb minőség, magasabb költség.','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Hagyjon üresen egy modellszámot, hogy a beépített alapértelmezést használja az adott szinthez. A helyőrző szöveg mutatja, melyik modellt fogja használni.','Translation Limits & Behavior'=>'Fordítási korlátok és viselkedés','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Fordítási korlátok: irányítsa, mely felhasználói szerepkörök indíthatnak AI fordítást, és állítson be havi tokenkeretet. A keret túllépése esetén az AI hívások szünetelnek a hónap újraindulásáig.','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Viselkedés: válassza ki az AI előbeállítást (Szerint, Egyensúly, Kreatív), adjon hozzá oldal-átívelő egyedi utasításokat, engedélyezze vagy tiltsa le az automatikus bejegyzés mentése utáni fordítást, és konfigurálja a Fordítási Memóriát.','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'A Fordítási memória gyorsítótárazza az AI eredményeket tartalom hash, nyelvpár, szolgáltató és modell szerint. Egy bejegyzés szerkesztése érvényteleníti a gyorsítótár bejegyzését, így a következő fordítási hívás friss eredményt kap.','Router Tab'=>'Router lap','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Elsődleges nyelv: az a nyelv, amelyen a meglévő tartalma íródott. Minden fordítás ebből a nyelvből készül; ennek megváltoztatása nem mozgat vagy töröl bejegyzéseket.','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL-struktúra: útvonal-előtag mód (példa.com/de/) nem igényel szerver módosítást. Alcímszó mód (de.pelda.com) wildcard DNS rekordot, wildcard SSL tanúsítványt és webszerver konfigurációs változtatást igényel — lásd a Szerver beállítási útmutatót.','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Aktív nyelvek: adj hozzá minden támogatni kívánt nyelvet. Minden nyelvhez tartozik egy URL-előtag vagy aldomain, valamint egy hreflang címke a lap &lt;head&gt; részében.','WP site language requirement'=>'WP oldal nyelvi követelmény','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'A WordPress oldal nyelvét (Beállítások → Általános → Oldal nyelve) olyan nyelvre kell állítani, amelyet a tartalomhoz használ — vagy a fő tartalomnyelvre, vagy valamelyik másodlagos nyelvre. Nem lehet olyan nyelv, amelyen nincs tartalom az oldalon.','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'Egy támogatott konfiguráció példája: WP oldal nyelve = CA (katalán), tartalomnyelvek = CA + ES.','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'Egy nem támogatott konfiguráció példája: WP oldal nyelve = EN (angol), tartalomnyelvek = CA + ES csak. Az angol nem tartalomnyelv, így a Lingua Forge nem tudja leképezni a WP helyi beállítást fordítási csoportokra.','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'Amikor a WP oldal nyelve nem tartalmi nyelv: a WooCommerce terméklekérdezések null eredményt adnak az összes katalógus blokkban; a termékkép delegálás sikertelen; minden nyelvi szűrővel ellátott tartalom lekérdezés megszakad; a nyelvváltó hamis nem-tartalmi nyelvi lehetőséget mutathat. Ha piros konfigurációs figyelmeztetést lát a Router vagy a Rendszer fül tetején, először javítsa ki az oldal nyelvét.','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE lokalizáció: keret, fordítás és linkek javítása a Full Site Editing sablonokban és sablonrészekben közvetlenül ebből a lapból.','Glossary Tab'=>'Szótár lap','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Jelölje ki azokat a kifejezéseket, amelyeket nem szabad fordítani vagy mindig bizonyos módon kell megjeleníteni (pl. márkanevek, terméknevek, rövidítések). A szótár korlátozásokat minden AI fordítási kérésbe beépítjük: bejegyzés fordítás, meta leírás, kivonat és FSE sablon fordítás.','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Adj egy kifejezést soronként. Mind a forráskifejezés, mind a célnyelvi megjelenítés kötelező. A nyelvpár határozza meg, mely fordítási feladatokra vonatkozik a korlátozás.','SEO Tab'=>'SEO fül','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'A Lingua Forge egy teljes körű többnyelvű SEO megoldás. Nincs szükség további SEO vagy oldal térkép bővítményre.','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Az LF által nyújtott: hreflang címkék minden konfigurált nyelvhez, Open Graph és Twitter Card címkék og:locale és og:locale:alternate, Schema.org JSON-LD nyelvi annotációkkal, valamint egy dedikált többnyelvű sitemap az /lf-sitemap.xml címen, xhtml:link alternatív bejegyzésekkel minden fordítási csoporthoz.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'A sitemap automatikusan be van jelentve a robots.txt-ben. Minden fő keresőmotor — Google, Bing, Yandex — megtalálja a robots.txt-ből. Nincs szükség manuális benyújtásra.','SEO plugins and conflict avoidance:'=>'SEO pluginok és konfliktus elkerülése:','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Ha Yoast SEO, Rank Math, All in One SEO vagy SEOPress van telepítve, a Lingua Forge felismeri őket, és alkalmazkodik a duplikált kimenet elkerülése érdekében. A hreflang esetében LF teljesen átveszi az irányítást, és elnyomja a bővítmény kimenetét, mert ezek a bővítmények nem képesek helyes hreflang-et előállítani többnyelvű útvonal konfigurációhoz. Az Open Graph esetében LF csak og:locale és og:locale:alternate jeleket ad hozzá — a többnyelvű jeleket, amelyeket a bővítmény nem tud biztosítani — és a bázis OG készletet a bővítményre hagyja. A Schema.org esetében LF teljesen letiltja saját kimenetét, hogy elkerülje az összeférhetetlen JSON-LD gráfokat.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'Az SEO → Kompatibilitás fül mutatja az élő észlelési állapotot, és pontosan elmagyarázza, mit tesz a LF minden funkcióterületen.','SEO Scores'=>'SEO pontszámok','SEO Score System'=>'SEO pontozási rendszer','Score computation'=>'Pontszámítás','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'Minden poszt 0–100 pontot kap hat szabályalapú mérőszám alapján: cím, meta leírás, szó száma, fejléc szerkezet, kép alt lefedettség, és belső hivatkozások. Tíz pont mindig jár az olvasási időért (csak információs célokra). A fennmaradó 90 pontot a többi mérőszám között osztják szét, súlyokkal, amelyek a tartalomprofil szerint változnak (lásd alább).','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'Minden mérőszám négy státusz egyikét adja: ok (teljes súly), figyelmeztetés (50 % a súlyból), sikertelen (0), vagy információ (0, nincs büntetés). A 80 vagy több pont zöld, 50–79 sárga, 50 alatt piros.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'Cím pontozási szabályok (minden profil): hibás, ha üres; figyelmeztetés, ha kevesebb mint 10 karakter; figyelmeztetés, ha csak egy szó; figyelmeztetés, ha hosszabb a profil SERP korlátjánál (60 karakter a Blog, 70 a Termék/Landing); rendben, ha legalább 10 karakter, legalább 2 szó, és a SERP korlátján belül van.','Content profiles and weights'=>'Tartalomprofilok és súlyok','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'A profilok alkalmazkodnak a tartalom típusához, amelyet elemeznek. A profil automatikusan megoldódik; felülírhatja azt az elemzési futás során a profil legördülőből.','Blog / Editorial (default)'=>'Blog / Szerkesztő (alapértelmezett)','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'Cím 15 pont · Meta leírás 20 pont · Szó száma 15 pont · Fejezetek 20 pont · Képek 10 pont · Hivatkozások 10 pont. A cím SERP korlátja 60 karakter; meta 120–210 karakter; szó száma figyelmeztet 300 alatt, hibázik 100 alatt; H2 szükséges; belső hivatkozások szükségesek.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'Automatikusan észlelt a WooCommerce termékekhez. Cím 20 pont · Meta leírás 30 pont · Szó száma 15 pont · Fejlécsor 5 pont · Képek 20 pont · Hivatkozások 0 pont. A cím SERP korlátja 70 karakter; a szó száma figyelmeztet 80 alatt, hibázik 40 alatt; az H2 és a belső hivatkozások opcionálisak.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'Automatikusan észlelt a statikus főoldalhoz; manuálisan is kiválasztható. Cím 20 pont · Meta leírás 30 pont · Szó száma 15 pont · Fejlécsor 10 pont · Képek 15 pont · Hivatkozások 0 pont. A cím SERP korlátja 70 karakter; a szó száma figyelmeztet 150 alatt, hibázik 60 alatt; az H2 és a belső hivatkozások opcionálisak.','Heading structure rules'=>'Fejléc szerkezeti szabályok','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'Pontosan egy H1 szükséges. A H1 általában a téma által renderelt poszt cím — élő oldalról olvasható be, ha lehetséges, és poszt tartalmából, mint alternatíva.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'Amikor a Blog profil H2-t igényel, és nem található, az elemző először H3 alcímeket ellenőriz, mielőtt figyelmeztetést adna. Az Accordion és Details blokkok alapértelmezés szerint H3-at használnak fejlécként; ezek az H3-asok elfogadottak érvényes szerkezetként és jó eredményt adnak, nem figyelmeztetést.','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'A rövid tartalom (legfeljebb 3 bekezdés) soha nem büntetendő hiányzó alcímekért, függetlenül a profiltól. Egy tömör oldal nem profitál a kényszerített fejlécstruktúrából.','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"Az H2-t H1-hez hasonlóként kezeljük" (Beállítások → SEO → Elemzés): engedélyezze ezt, ha a témája a poszt címet H2-ben jeleníti meg H1 helyett. Az elemző az első H2-t H1-re emeli, így a pontszám nem lesz helytelenül büntetve.','Score history and badges'=>'Pontszámítási előzmények és jelvények','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'Minden alkalommal, amikor egy posztot elemeznek, a pontszám elmentésre kerül a poszt meta adatában. A poszt lista Nyelv oszlopa színkódolt "SEO N" jelvényt mutat, ha a poszt legalább egyszer elemzésen esett át. Két pontszám tárolásakor egy delta jelző (↑N / ↓N) mutatja a változást az előző futás óta.','AI Usage & Cache Tab'=>'AI Használat & Gy cache fül','Token usage'=>'Token használat','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'A használati táblázat az AI token fogyasztást bontja fel funkció (fordítás, meta leírás, kivonat, FSE sablon, csoportos elemzés), szolgáltató és modell szerint. Használja a dátumtartomány gombokat a mai, az elmúlt 7 nap, az elmúlt 30 nap vagy az összes idő szerint történő szűréshez.','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'A napi kvótát (a Viselkedés → Határok alatt konfigurálva) itt követjük nyomon. Amikor a kvóta eléri a határt, az AI hívások szünetelnek a nap hátralévő részében. A táblázat mutatja, mennyi kvótát használtak fel.','Translation caching'=>'Fordítás gyorsítótárazás','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'A Lingua Forge két független gyorsítótárazási réteget használ az ismétlődő AI API hívások csökkentése érdekében:','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'Tárolja a nyers AI válaszokat, kulcsokat tartalmazó hash szerint, nyelvpár, szolgáltató, modell és előbeállítás szerint. A gyorsítótár bejegyzései automatikusan érvénytelenek lesznek, amikor a forrás bejegyzés tartalma megváltozik. Törölje az egyes bejegyzéseket vagy az egész gyorsítótárat ebből a fülből.','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'Tárolja a teljes fordított bejegyzés kimenetet hash szerint. Beállítás szerint (a Viselkedésben). Gyorsítja az ismételt fordításokat változatlan tartalom esetén. Törölje innen, ha friss AI feldolgozást akar, függetlenül attól, hogy a tartalom megváltozott-e.','Maintenance Tab'=>'Karbantartási lap','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Nyelvi felülírások: kezelje a testreszabott .po/.mo felülíró fájlokat a Lingua Forge UI szövegeihez. Használja ezt ahelyett, hogy közvetlenül szerkesztené a bővítmény fájljait — a felülírások megmaradnak a frissítések során.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Hibakeresés: engedélyezze a hibakereső naplót, hogy rögzítse az AI utasításokat és az API válaszokat egy helyi fájlba. Kikapcsolás a hibakeresés után — a hibakereső mód minden AI kérésnél ír egy fájlt.','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'Eltávolítási viselkedés: szabályozza, mi kerül törlésre, amikor a bővítményt eltávolítja a Bővítmények → Telepített bővítmények → Törlés menüpontból. A bővítmény beállításai és az AI gyorsítótárak mindig törlésre kerülnek. A nyelvi hozzárendeléseket, fordítási kapcsolatokat, meta leírásokat, szójegyzéket és Fordítási Memóriát alapértelmezés szerint megtartják, így véletlen eltávolítás vagy újratelepítés esetén folytathatja ott, ahol abbahagyta. Engedélyezze az „Adatok törlése az eltávolításkor” opciót csak akkor, ha teljes mértékben eltávolítja a többnyelvű támogatást az oldalról — ez nem vonható vissza.','System Tab'=>'Rendszer fül','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'Csak olvasható diagnosztika a jelenlegi telepítéshez. Itt nem változtatunk beállításokat — használja a konfiguráció ellenőrzéséhez, problémák észleléséhez, valamint hibajelentésekhez.','Sections'=>'Szekciók','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Lingua Forge, WordPress és PHP verziók; aktív téma; URL szerkezet; WP oldal nyelv és elsődleges tartalomnyelv. A WP oldal nyelv melletti piros jelző azt jelenti, hogy nem tartalomnyelv — javítsa ezt a Beállítások → Általános menüben, mielőtt bármi mást csinálna.','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'Aktív szolgáltató, konfigurált kulcsok, modell szintek kiválasztása, előbeállítás és napi kvóta.','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'Megerősíti, hogy a permalink szerkezet kompatibilis a Lingua Forge útvonalkezelésével. Az egyszerű és csak numerikus szerkezetek nem támogatottak.','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'Listázza az összes aktív harmadik fél által készített SEO bővítményt. A Lingua Forge alkalmazkodik ezekhez — lásd Beállítások → SEO → Kompatibilitás a funkciók szerinti bontásért.','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'WooCommerce verzió, rendelés tárolási mód (CPT / HPOS / megosztott), és egy nyelvenkénti fordítási lefedettségi táblázat a négy beépített WC oldalhoz (Bolt, Kosár, Pénztár, Saját fiók).','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'Listázza azokat a bejegyzéstípusokat, amelyek közzétett bejegyzéseket tartalmaznak _lf_lang meta érték nélkül. A hiányzó címkéjű bejegyzések láthatatlanok minden nyelvi szűrő számára. Használja a Javítás gombot, hogy címkézze őket a forrásnyelvvel, vagy az Exclude-t, hogy teljesen eltávolítsa a bejegyzéstípust a nyelvi útvonalból.','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'Összes LF tulajdonában lévő bejegyzés összefoglalója a $wp_rewrite->extra_rules_top-ban. Hasznos 404-es hibák vagy útvonal konfliktusok diagnosztizálásához, miután új nyelvet adtunk hozzá.','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'Egy kattintással másolható egy egyszerű szöveges rendszer összefoglaló, amely az összes fent említett szekciót tartalmazza. Illessze be ezt egy GitHub hibajegybe vagy támogatási kérésbe, így az összes környezet áttekinthető.','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'Találtál hibát vagy váratlan viselkedést? Kérjük, nyiss egy hibajegyet a GitHubon — csatold a fent említett Hibakeresési Információ blokkot és egy rövid leírást arról, mit vártál és mi történt.','Open an issue →'=>'Nyisson meg egy hibát →','Getting started'=>'Elindulás','Server setup (subdomain)'=>'Szerver beállítás (aldomain)','Translation workflow'=>'Fordítási munkafolyamat','Language switcher'=>'Nyelvváltó','WP-CLI reference'=>'WP-CLI referencia','Integration API'=>'Integrációs API','Documentation'=>'Dokumentáció','Report an issue on GitHub'=>'Hiba jelentése a GitHubon','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','WordPress AI Client (WP 7.0+)'=>'WordPress AI kliens (WP 7.0+)','Meta Description, Excerpt Generator'=>'Meta leírás, kivonat generátor','Translation, Content Generator'=>'Fordítás, Tartalom Generátor','Testing…'=>'Tesztelés…','✓ Connection OK'=>'✓ Kapcsolat rendben','✗ Failed:'=>'✗ Sikertelen:','No response from provider — check the error log for details.'=>'Nincs válasz a szolgáltatótól — ellenőrizze a hibajegyet a részletekért.','Network error — could not reach the WordPress AJAX endpoint.'=>'Hálózati hiba — nem lehet elérni a WordPress AJAX végpontot.','Translating a real post with this model…'=>'Valós bejegyzés fordítása ezzel a modellel…','preset'=>'előbeállítás','Loading…'=>'Betöltés…','Installing…'=>'Telepítés…','✓ Language installed.'=>'✓ Nyelv telepítve.','✗ Error:'=>'✗ Hiba:','Creating…'=>'Létrehozás…','✓ All templates created.'=>'✓ Minden sablon létrehozva.','Some templates could not be created.'=>'Néhány sablont nem sikerült létrehozni.','Recreating…'=>'Újbóli létrehozás…','✓ All templates recreated.'=>'✓ Az összes sablon újra lett hozva.','Some templates could not be recreated.'=>'Néhány sablont nem lehetett újra létrehozni.','This overwrites this template with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Ez felülírja ezt a sablont az aktív téma friss másolatával, elvetéve a Weboldal-szerkesztőben végzett módosításokat. Ez nem vonható vissza. Folytatás?','This overwrites every template with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Ez felülírja az összes sablont az aktív téma friss másolatával, elvetéve a Weboldal-szerkesztőben végzett módosításokat. Ez nem vonható vissza. Folytatás?','✓ All parts recreated.'=>'✓ Az összes rész újra lett hozva.','Some parts could not be recreated.'=>'Néhány részt nem lehetett újra létrehozni.','This overwrites this template part with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Ez felülírja ezt a sablon részt az aktív téma friss másolatával, elvetéve a Weboldal-szerkesztőben végzett módosításokat. Ez nem vonható vissza. Folytatás?','This overwrites every template part with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Ez felülírja az összes sablon részt az aktív téma friss másolatával, elvetéve a Weboldal-szerkesztőben végzett módosításokat. Ez nem vonható vissza. Folytatás?','✓ All parts created.'=>'✓ Minden rész létrehozva.','Some parts could not be created.'=>'Néhány részt nem sikerült létrehozni.','✓ All translated.'=>'✓ Minden fordítva.','Some translations failed.'=>'Néhány fordítás sikertelen volt.','Review carefully — links and slugs not updated.'=>'Alapos áttekintés — linkek és slugok nem frissültek.','Fixing…'=>'Javítás…','✓ Links fixed.'=>'✓ Linkek javítva.','Some link fixes failed.'=>'Néhány link javítása sikertelen volt.','✓ Parts fixed.'=>'✓ Részek javítva.','Some part fixes failed.'=>'Néhány rész javítása sikertelen volt.','✓ Nav refs fixed.'=>'✓ Navigációs hivatkozások javítva.','Some nav ref fixes failed.'=>'Néhány navigációs hivatkozás javítása sikertelen volt.','✓ Pattern translated.'=>'✓ Minta fordítva.','Pattern translation failed.'=>'A minta fordítása sikertelen volt.','Hide'=>'Elrejtés','Re-create all templates'=>'Az összes sablon újbóli létrehozása','Re-create all parts'=>'Az összes rész újbóli létrehozása','This runs Re-create all templates, Re-create all parts, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time. It overwrites existing templates and parts with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template and part, which may take a while and may incur cost depending on your provider. Continue?'=>'Ez futtatja az Összes sablon újbóli létrehozása, Összes rész újbóli létrehozása, Összes fordítása, Összes rész javítása és Összes hivatkozás javítása műveleteket az összes {total} aktív nyelvhez, egyik nyelvről a másikra. Ez felülírja az aktív témából származó meglévő sablonokat és részeket (elvetéve a Weboldal-szerkesztő testreszabásait) és újra fordítja a tartalmakat — ezek közül semmi sem vonható vissza. Az Összes fordítása valódi AI API hívásokat végez minden sablonhoz és részhez, ami hosszú ideig tarthat és költségeket eredményezhet a szolgáltatótól függően. Folytatás?','This runs Re-create all templates, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time — template parts (headers, footers, etc.) are left untouched. It overwrites existing templates with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template, which may take a while and may incur cost depending on your provider. Continue?'=>'Ez futtatja az Összes sablon újbóli létrehozása, Összes fordítása, Összes rész javítása és Összes hivatkozás javítása műveleteket az összes {total} aktív nyelvhez, egyik nyelvről a másikra — a sablon részek (fejlécek, lábléc stb.) érintetlenek maradnak. Ez felülírja az aktív témából származó meglévő sablonokat (elvetéve a Weboldal-szerkesztő testreszabásait) és újra fordítja a tartalmakat — ezek közül semmi sem vonható vissza. Az Összes fordítása valódi AI API hívásokat végez minden sablonhoz, ami hosszú ideig tarthat és költségeket eredményezhet a szolgáltatótól függően. Folytatás?','This runs Re-create all parts (headers, footers, and every other template part) for every one of your {total} active languages, one language at a time. It overwrites existing template parts with fresh copies from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Ez futtatja az Összes rész újbóli létrehozása (fejlécek, láblécek és minden más sablon rész) műveletet az összes {total} aktív nyelvhez, egyik nyelvről a másikra. Ez felülírja az aktív témából származó meglévő sablon részeket, elvetéve a Weboldal-szerkesztőben végzett módosításokat. Ez nem vonható vissza. Folytatás?','Starting…'=>'Indítás…','Processing {lang} ({index} of {total}) — {step}…'=>'Feldolgozás: {lang} ({index} / {total}) — {step}…','Cancelled.'=>'Visszavonva.','{done} of {total} languages processed.'=>'{done} / {total} nyelvből feldolgozva.','⚠ Done with issues.'=>'⚠ Kész, de hibák adódtak.','✓ All {total} languages processed.'=>'✓ Az összes {total} nyelv feldolgozva.','Built-in preset instructions:'=>'Beépített előre beállított utasítások:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Nincs beépített utasítás — minden AI funkció saját hangolt alapértelmezéseket használ. Töltse ki az alábbi Egyéni prompt utasítások mezőt, hogy saját szabályokat adjon hozzá az oldal egészére.','Modified'=>'Módosítva','edit'=>'szerkesztés','No published posts found for the selected filters.'=>'Nem található közzétett bejegyzés a kiválasztott szűrőkkel.','Just now'=>'Most rögtön','Score'=>'Pontszám','Source title'=>'Forrás cím','Multilingual SEO overview'=>'Többnyelvű SEO áttekintése','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'A pontszám jelzés, nem ítélet. Egyes tartalmak szerkezetileg korlátozottak — nagyon rövid oldalak, landoló oldalak kevés szöveggel, vagy olyan oldalak, amelyek célja a navigáció, nem az információ, természetüknél fogva alacsonyabb pontszámot adhatnak. Használja ezt az áttekintést, hogy valódi parity hiányokat fedezzen fel a nyelvek között, nem pedig a szám követésére.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'Ez egy WooCommerce rendszeroldal (Bolt, Kosár, Fizetés stb.). Tartalmát a WooCommerce kezeli — a pontszám csak szerkezeti jeleket tükröz, nem szerkeszthető SEO tartalmat.','Settings'=>'Beállítások','You do not have permission to manage these settings.'=>'Nincs jogosultsága ezeknek a beállításoknak a kezelésére.','Lingua Forge — Settings'=>'Lingua Forge — Beállítások','Settings saved.'=>'A beállítások mentve.','Save Settings'=>'Beállítások mentése','Standard'=>'Alapértelmezett','Technical / Scientific'=>'Technikai / Tudományos','Legal / Compliance'=>'Jogi / Megfelelőség','Creative / Marketing'=>'Kreatív / Marketing','Lingua Forge — AI Usage Statistics'=>'Lingua Forge — Mesterséges intelligencia használati statisztikái','Lingua Forge AI Usage Statistics'=>'Lingua Forge AI Használati Statisztikák','Date'=>'Dátum','Request count'=>'Kérések száma','Full Article'=>'Teljes cikk','Introduction only'=>'Csak 